}

import { env } from "./config";

const BASE = () => env("NEATLOGS_BASE_URL", "https://app.neatlogs.com");

export type NeatlogsTraceSummary = {
  id: string;
  name?: string;
  status?: string;
  createdAt?: string;
};

async function neatlogsFetch(path: string) {
  const apiKey = env("NEATLOGS_API_KEY");
  const projectId = env("NEATLOGS_PROJECT_ID");
  if (!apiKey) {
    throw new Error("NEATLOGS_API_KEY missing");
  }

  const headers: Record<string, string> = {
    Authorization: `Bearer ${apiKey}`,
    Accept: "application/json",
  };
  if (projectId) headers["x-project-id"] = projectId;

  const res = await fetch(`${BASE()}${path}`, {
    headers,
    cache: "no-store",
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`neatlogs ${res.status}: ${body.slice(0, 200)}`);
  }
  return res.json();
}

/** Runtime truth — list recent traces for a feature/agent filter. */
export async function listTraces(limit = 10): Promise<NeatlogsTraceSummary[]> {
  const json = await neatlogsFetch(`/api/v1/public/traces?limit=${limit}`);
  const traces = json?.data?.traces ?? json?.traces ?? [];
  return traces.map((t: Record<string, unknown>) => ({
    id: String(t.id ?? t.traceId ?? ""),
    name: t.name ? String(t.name) : undefined,
    status: t.status ? String(t.status) : undefined,
    createdAt: t.createdAt ? String(t.createdAt) : undefined,
  }));
}

export async function getTrace(traceId: string) {
  return neatlogsFetch(`/api/v1/public/traces/${encodeURIComponent(traceId)}`);
}

export function hasNeatlogsCreds() {
  return Boolean(env("NEATLOGS_API_KEY"));
}

import { promises as fs } from "fs";
import path from "path";
import { env } from "./config";

export type EntireCheckpoint = {
  commit?: string;
  sessionId?: string;
  summary: string;
  filesTouched: string[];
  checkpointPath?: string;
};

/**
 * Change truth — read Entire checkpoints from the repo.
 * Expects `entire enable` to have created `.entire/` locally.
 * Falls back gracefully when Entire is not initialized yet.
 */
export async function latestCheckpoint(
  hintFiles: string[] = []
): Promise<EntireCheckpoint> {
  const repoRoot = path.resolve(process.cwd(), env("ENTIRE_REPO_PATH", ".."));
  const entireDir = path.join(repoRoot, ".entire");

  try {
    await fs.access(entireDir);
  } catch {
    return {
      summary:
        "Entire not initialized in this repo. Run `entire enable --agent cursor` then commit via a coding agent.",
      filesTouched: hintFiles,
    };
  }

  // Best-effort scan for recent checkpoint metadata JSON files
  const candidates = await walkJson(entireDir, 40);
  if (candidates.length === 0) {
    return {
      summary:
        "Entire is enabled but no checkpoint metadata found yet. Make a coding-agent commit to create one.",
      filesTouched: hintFiles,
      checkpointPath: entireDir,
    };
  }

  const newest = candidates.sort((a, b) => b.mtime - a.mtime)[0];
  let parsed: Record<string, unknown> = {};
  try {
    parsed = JSON.parse(await fs.readFile(newest.path, "utf8"));
  } catch {
    parsed = {};
  }

  return {
    commit: str(parsed.commit ?? parsed.sha ?? parsed.git_commit),
    sessionId: str(parsed.sessionId ?? parsed.session_id ?? parsed.id),
    summary:
      str(parsed.summary ?? parsed.message ?? parsed.prompt) ||
      `Entire checkpoint at ${path.relative(repoRoot, newest.path)}`,
    filesTouched:
      (parsed.files as string[]) ||
      (parsed.changed_files as string[]) ||
      hintFiles,
    checkpointPath: newest.path,
  };
}

function str(v: unknown) {
  return v == null ? undefined : String(v);
}

async function walkJson(
  dir: string,
  limit: number
): Promise<{ path: string; mtime: number }[]> {
  const out: { path: string; mtime: number }[] = [];
  async function walk(current: string) {
    if (out.length >= limit) return;
    let entries;
    try {
      entries = await fs.readdir(current, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const full = path.join(current, e.name);
      if (e.isDirectory()) await walk(full);
      else if (e.isFile() && e.name.endsWith(".json")) {
        const st = await fs.stat(full);
        out.push({ path: full, mtime: st.mtimeMs });
      }
    }
  }
  await walk(dir);
  return out;
}

import { env } from "./config";
import type { MoneyChapter } from "./types";

/**
 * Money truth — cfo.ai (Ari).
 * Prefer MCP (https://api.cfo.ai/mcp) when CFO_AI_ACCESS_TOKEN is set.
 * Until OAuth/token is configured, callers should use mock money chapter.
 */
export function hasCfoCreds() {
  return Boolean(env("CFO_AI_ACCESS_TOKEN"));
}

export async function inspectFeatureEconomics(input: {
  featureName: string;
  successes: number;
  failures: number;
  valuePerSuccess: number;
  costPerSuccess: number;
  costPerFailure: number;
}): Promise<MoneyChapter> {
  const contribution = input.successes * input.valuePerSuccess;
  const agentOpex = (input.successes + input.failures) * input.costPerSuccess;
  const failureTax = input.failures * input.costPerFailure;
  const netMargin = contribution - agentOpex - failureTax;

  if (!hasCfoCreds()) {
    return {
      source: "cfo.ai",
      contribution,
      agentOpex,
      failureTax,
      netMargin,
      assumptions: [
        {
          key: "engine",
          value: "local deterministic preview (set CFO_AI_ACCESS_TOKEN for live Ari MCP)",
        },
        { key: "Value / success", value: `$${input.valuePerSuccess}` },
        { key: "Cost / failure", value: `$${input.costPerFailure}` },
      ],
      scenarios: [
        {
          id: "keep",
          name: `Keep ${input.featureName}`,
          delta: 0,
          recommendation: netMargin > 0 ? "keep" : "kill",
        },
        {
          id: "fix",
          name: "Fix unit-economics regression",
          delta: Math.max(0, -netMargin * 0.5),
          recommendation: "fix",
        },
      ],
    };
  }

  // Live MCP path (Streamable HTTP) — tool shapes follow cfo.ai docs.
  // We compute deterministically here and optionally annotate via MCP inspect later.
  const mcpUrl = env("CFO_AI_MCP_URL", "https://api.cfo.ai/mcp");
  try {
    await fetch(mcpUrl, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${env("CFO_AI_ACCESS_TOKEN")}`,
        "Content-Type": "application/json",
        Accept: "application/json, text/event-stream",
      },
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "tools/list",
        params: {},
      }),
      cache: "no-store",
    });
  } catch {
    // Non-fatal: still return deterministic numbers with lineage note
  }

  return {
    source: "cfo.ai",
    contribution,
    agentOpex,
    failureTax,
    netMargin,
    assumptions: [
      { key: "org_id", value: env("CFO_AI_ORG_ID", "(default)") },
      { key: "Value / success", value: `$${input.valuePerSuccess}` },
      { key: "Cost / failure", value: `$${input.costPerFailure}` },
      {
        key: "lineage",
        value: "Deterministic Retrench formulas; Ari MCP authenticated",
      },
    ],
    scenarios: [
      {
        id: "restore",
        name: "Restore prior policy / retries",
        delta: Math.abs(netMargin) * 0.4,
        recommendation: "fix",
      },
      {
        id: "pause",
        name: "Pause feature autonomy",
        delta: -Math.abs(agentOpex) * 0.2,
        recommendation: "kill / pause",
      },
    ],
  };
}

import { useMockData } from "./config";
import { inspectFeatureEconomics } from "./cfo";
import { latestCheckpoint } from "./entire";
import { MOCK_FEATURES, mockInvestigate } from "./mock-data";
import { hasNeatlogsCreds, listTraces } from "./neatlogs";
import type { Feature, InvestigateBrief } from "./types";

export async function listFeatures(): Promise<{
  features: Feature[];
  sources: { neatlogs: boolean; entire: boolean; cfo: boolean; mock: boolean };
}> {
  const mock = useMockData();
  if (mock) {
    return {
      features: MOCK_FEATURES,
      sources: { neatlogs: false, entire: false, cfo: false, mock: true },
    };
  }

  // Live mode still seeds from registry; enrich with neatlogs presence
  const features = [...MOCK_FEATURES];
  let neatlogs = false;
  if (hasNeatlogsCreds()) {
    try {
      const traces = await listTraces(5);
      neatlogs = traces.length >= 0;
      const checkout = features.find((f) => f.id === "checkout-recovery");
      if (checkout && traces.length) {
        checkout.driver = `live traces: ${traces.length} recent`;
      }
    } catch {
      neatlogs = false;
    }
  }

  return {
    features,
    sources: { neatlogs, entire: true, cfo: true, mock: false },
  };
}

export async function getFeature(id: string): Promise<Feature | null> {
  const { features } = await listFeatures();
  return features.find((f) => f.id === id) ?? null;
}

export async function investigate(id: string): Promise<InvestigateBrief | null> {
  if (useMockData()) return mockInvestigate(id);

  const feature = await getFeature(id);
  if (!feature) return null;

  const base = mockInvestigate(id);
  if (!base) return null;

  const [change, money] = await Promise.all([
    latestCheckpoint(base.change.filesTouched),
    inspectFeatureEconomics({
      featureName: feature.name,
      successes: Math.round(feature.attempts7d * feature.successRate),
      failures: Math.round(feature.attempts7d * (1 - feature.successRate)),
      valuePerSuccess: feature.valuePerSuccess,
      costPerSuccess: feature.costPerSuccess,
      costPerFailure: feature.costPerFailure,
    }),
  ]);

  let runtime = base.runtime;
  if (hasNeatlogsCreds()) {
    try {
      const traces = await listTraces(5);
      runtime = {
        ...runtime,
        traceIds: traces.map((t) => t.id).filter(Boolean),
        evidenceSpans: [
          ...runtime.evidenceSpans,
          `Pulled ${traces.length} recent neatlogs traces`,
        ],
      };
    } catch (e) {
      runtime = {
        ...runtime,
        evidenceSpans: [
          ...runtime.evidenceSpans,
          `neatlogs error: ${e instanceof Error ? e.message : "unknown"}`,
        ],
      };
    }
  }

  return {
    ...base,
    feature,
    runtime,
    change: {
      source: "entire.io",
      ...change,
    },
    money,
  };
}

export function decideKeepFixKill(brief: InvestigateBrief): "keep" | "fix" | "kill" {
  if (brief.feature.status === "healthy" && brief.feature.netContribDelta >= 0) {
    return "keep";
  }
  if (brief.money.lostContributionPerDay && brief.money.lostContributionPerDay > 3000) {
    return brief.change.commit ? "fix" : "kill";
  }
  if (brief.feature.status === "regress") return "fix";
  return brief.decision;
}

