"""
Demo production agent for Retrench — Checkout Recovery.

Instrument with neatlogs so runtime truth lands in the dashboard.
Requires: pip install neatlogs openai
Env: NEATLOGS_API_KEY, OPENAI_API_KEY
"""

from __future__ import annotations

import os

import neatlogs
from openai import OpenAI

neatlogs.init(
    api_key=os.environ.get("NEATLOGS_API_KEY")
    or os.environ.get("NEATLOGS_PROJECT_API_KEY"),
    workflow_name="checkout_recovery",
)

client = neatlogs.wrap(OpenAI())


@neatlogs.span(kind="WORKFLOW")
def run_checkout_recovery(order_id: str, customer_note: str) -> str:
    """Simulates the checkout_agent feature Retrench tracks."""
    completion = client.chat.completions.create(
        model="gpt-4.1-mini",
        messages=[
            {
                "role": "system",
                "content": (
                    "You are checkout_agent. Complete failed checkouts without "
                    "double-charging. Prefer bounded retries. Never invent charges."
                ),
            },
            {
                "role": "user",
                "content": f"Order {order_id}. Customer: {customer_note}",
            },
        ],
    )
    return completion.choices[0].message.content or ""


if __name__ == "__main__":
    print(
        run_checkout_recovery(
            "NL-10482",
            "Checkout keeps timing out. Do not charge Maya twice.",
        )
    )

