import Link from "next/link";
import {
  ArrowLeft,
  CircleDollarSign,
  GitCommitHorizontal,
  Radar,
} from "lucide-react";
import { StatusBadge } from "@/components/status-badge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import type { InvestigateBrief } from "@/lib/types";

function money(n: number) {
  const sign = n < 0 ? "-" : "";
  return `${sign}$${Math.abs(n).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
}

const decisionStyles = {
  keep: "bg-emerald-700 text-white hover:bg-emerald-700",
  fix: "bg-amber-600 text-white hover:bg-amber-600",
  kill: "bg-red-700 text-white hover:bg-red-700",
} as const;

export function InvestigateView({ brief }: { brief: InvestigateBrief }) {
  const { feature, runtime, change, money: mon, decision, fixBrief } = brief;

  return (
    <div className="mx-auto flex w-full max-w-5xl flex-col gap-8 px-4 py-10 sm:px-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <Link
            href="/"
            className={cn(
              buttonVariants({ variant: "ghost", size: "sm" }),
              "-ml-2 mb-3 gap-1.5"
            )}
          >
            <ArrowLeft className="size-3.5" />
            Portfolio
          </Link>
          <h1 className="text-3xl font-semibold tracking-tight">
            {feature.name}
          </h1>
          <p className="mt-1 text-muted-foreground">
            Agents:{" "}
            <span className="font-mono text-sm">{feature.agents.join(" → ")}</span>
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <StatusBadge status={feature.status} />
          <Badge
            className={cn(
              "rounded-md uppercase tracking-wide",
              decisionStyles[decision]
            )}
          >
            {decision}
          </Badge>
        </div>
      </div>

      <Alert className="border-primary/20 bg-card shadow-sm">
        <AlertTitle className="text-base">
          Retrench decision: {decision}
        </AlertTitle>
        <AlertDescription className="text-sm leading-relaxed">
          {fixBrief}
        </AlertDescription>
      </Alert>

      <Tabs defaultValue="runtime" className="gap-4">
        <TabsList className="h-auto w-full flex-wrap justify-start gap-1 bg-muted/60 p-1">
          <TabsTrigger value="runtime" className="gap-1.5">
            <Radar className="size-3.5" />
            Runtime · neatlogs
          </TabsTrigger>
          <TabsTrigger value="change" className="gap-1.5">
            <GitCommitHorizontal className="size-3.5" />
            Change · entire.io
          </TabsTrigger>
          <TabsTrigger value="money" className="gap-1.5">
            <CircleDollarSign className="size-3.5" />
            Money · cfo.ai
          </TabsTrigger>
        </TabsList>

        <TabsContent value="runtime" className="mt-0">
          <Card className="shadow-sm">
            <CardHeader>
              <CardTitle>What happened</CardTitle>
              <CardDescription>
                Success {(runtime.successRate * 100).toFixed(0)}% · Cost /
                success ${runtime.costPerSuccess.toFixed(2)}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {runtime.openIncidents.length === 0 ? (
                <p className="text-sm text-muted-foreground">
                  No open incidents.
                </p>
              ) : (
                runtime.openIncidents.map((i) => (
                  <div
                    key={i.id}
                    className="rounded-xl border bg-muted/30 p-4 text-sm"
                  >
                    <div className="font-medium">
                      {i.id} — {i.title}
                    </div>
                    <div className="mt-1 text-muted-foreground">
                      {i.failingRuns} failing runs
                    </div>
                  </div>
                ))
              )}
              <Separator />
              <div>
                <div className="mb-2 text-sm font-medium">Evidence</div>
                <ul className="space-y-2 text-sm text-muted-foreground">
                  {runtime.evidenceSpans.map((s) => (
                    <li key={s} className="flex gap-2">
                      <span className="mt-1.5 size-1.5 shrink-0 rounded-full bg-primary" />
                      {s}
                    </li>
                  ))}
                </ul>
              </div>
              {runtime.traceIds.length > 0 ? (
                <p className="font-mono text-xs text-muted-foreground">
                  Traces: {runtime.traceIds.join(", ")}
                </p>
              ) : null}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="change" className="mt-0">
          <Card className="shadow-sm">
            <CardHeader>
              <CardTitle>What changed</CardTitle>
              <CardDescription>
                {change.commit
                  ? `Commit ${change.commit}`
                  : "No commit linked yet"}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4 text-sm">
              <p className="leading-relaxed">{change.summary}</p>
              {change.sessionId ? (
                <p>
                  Session{" "}
                  <code className="rounded-md bg-muted px-1.5 py-0.5 font-mono text-xs">
                    {change.sessionId}
                  </code>
                </p>
              ) : null}
              {change.filesTouched.length > 0 ? (
                <div>
                  <div className="mb-2 font-medium">Files touched</div>
                  <ul className="space-y-1.5 font-mono text-xs text-muted-foreground">
                    {change.filesTouched.map((f) => (
                      <li
                        key={f}
                        className="rounded-md border bg-muted/20 px-2 py-1.5"
                      >
                        {f}
                      </li>
                    ))}
                  </ul>
                </div>
              ) : null}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="money" className="mt-0">
          <Card className="shadow-sm">
            <CardHeader>
              <CardTitle>What it costs</CardTitle>
              <CardDescription>
                Net margin {money(mon.netMargin)}
                {mon.lostContributionPerDay
                  ? ` · ~${money(mon.lostContributionPerDay)}/day at risk`
                  : ""}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-5 text-sm">
              <div className="grid gap-3 sm:grid-cols-3">
                <div className="rounded-xl border bg-muted/20 p-4">
                  <div className="text-muted-foreground">Contribution</div>
                  <div className="mt-1 text-xl font-semibold tracking-tight">
                    {money(mon.contribution)}
                  </div>
                </div>
                <div className="rounded-xl border bg-muted/20 p-4">
                  <div className="text-muted-foreground">Agent OpEx</div>
                  <div className="mt-1 text-xl font-semibold tracking-tight">
                    {money(mon.agentOpex)}
                  </div>
                </div>
                <div className="rounded-xl border bg-muted/20 p-4">
                  <div className="text-muted-foreground">Failure tax</div>
                  <div className="mt-1 text-xl font-semibold tracking-tight">
                    {money(mon.failureTax)}
                  </div>
                </div>
              </div>
              <Separator />
              <div>
                <div className="mb-2 font-medium">Assumptions (cfo.ai)</div>
                <ul className="space-y-1.5 text-muted-foreground">
                  {mon.assumptions.map((a) => (
                    <li key={a.key}>
                      <span className="text-foreground">{a.key}:</span> {a.value}
                    </li>
                  ))}
                </ul>
              </div>
              <div>
                <div className="mb-2 font-medium">Scenarios</div>
                <div className="space-y-2">
                  {mon.scenarios.map((s) => (
                    <div
                      key={s.id}
                      className="flex items-center justify-between gap-3 rounded-xl border p-4"
                    >
                      <div>
                        <div className="font-medium">{s.name}</div>
                        <div className="text-muted-foreground">
                          {s.recommendation}
                        </div>
                      </div>
                      <div
                        className={cn(
                          "shrink-0 font-semibold",
                          s.delta < 0 ? "text-red-600" : "text-emerald-700"
                        )}
                      >
                        {s.delta >= 0 ? "+" : ""}
                        {money(s.delta)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

