import type { FeatureStatus } from "./types";

export type DecisionChoice = "keep" | "fix" | "kill";

export type RecordedDecision = {
  choice: DecisionChoice;
  at: string;
};

const KEY = "retrench:decisions:v1";

export function readDecisions(): Record<string, RecordedDecision> {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return {};
    return JSON.parse(raw) as Record<string, RecordedDecision>;
  } catch {
    return {};
  }
}

export function writeDecision(featureId: string, choice: DecisionChoice) {
  const next = {
    ...readDecisions(),
    [featureId]: { choice, at: new Date().toISOString() },
  };
  window.localStorage.setItem(KEY, JSON.stringify(next));
  window.dispatchEvent(new Event("retrench:decisions"));
  return next[featureId];
}

export function clearDecision(featureId: string) {
  const all = readDecisions();
  delete all[featureId];
  window.localStorage.setItem(KEY, JSON.stringify(all));
  window.dispatchEvent(new Event("retrench:decisions"));
}

export function statusFromDecision(choice: DecisionChoice): FeatureStatus {
  if (choice === "keep") return "healthy";
  if (choice === "fix") return "fixing";
  return "paused";
}

"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowRight, Check, Wrench, Ban } from "lucide-react";
import { Button, buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
  readDecisions,
  writeDecision,
  type DecisionChoice,
} from "@/lib/decisions";

const actions: {
  choice: DecisionChoice;
  label: string;
  hint: string;
  icon: typeof Check;
  className: string;
}[] = [
  {
    choice: "keep",
    label: "Keep",
    hint: "Economics are healthy — leave it running",
    icon: Check,
    className: "bg-emerald-700 text-white hover:bg-emerald-700/90",
  },
  {
    choice: "fix",
    label: "Fix",
    hint: "Ship the brief — restore margin",
    icon: Wrench,
    className: "bg-amber-600 text-white hover:bg-amber-600/90",
  },
  {
    choice: "kill",
    label: "Kill",
    hint: "Pause autonomy — stop the bleed",
    icon: Ban,
    className: "bg-red-700 text-white hover:bg-red-700/90",
  },
];

export function DecisionActions({
  featureId,
  recommended,
  nextFeatureId,
  nextFeatureName,
}: {
  featureId: string;
  recommended: DecisionChoice;
  nextFeatureId?: string;
  nextFeatureName?: string;
}) {
  const [recorded, setRecorded] = useState<DecisionChoice | null>(null);

  useEffect(() => {
    setRecorded(readDecisions()[featureId]?.choice ?? null);
  }, [featureId]);

  function choose(choice: DecisionChoice) {
    writeDecision(featureId, choice);
    setRecorded(choice);
  }

  return (
    <section className="retrench-enter retrench-enter-delay-3 space-y-4 rounded-2xl border bg-card p-5 shadow-sm sm:p-6">
      <div>
        <h2 className="text-base font-semibold tracking-tight">
          Your call
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Retrench recommends{" "}
          <span className="font-medium text-foreground uppercase">
            {recommended}
          </span>
          . Confirm to close the loop — this is stored in this browser for the
          portfolio walkthrough.
        </p>
      </div>

      <div className="grid gap-2 sm:grid-cols-3">
        {actions.map(({ choice, label, hint, icon: Icon, className }) => {
          const active = recorded === choice;
          return (
            <button
              key={choice}
              type="button"
              onClick={() => choose(choice)}
              className={cn(
                "flex flex-col items-start gap-1 rounded-xl border px-4 py-3 text-left transition",
                active
                  ? className
                  : "bg-background hover:bg-muted/60",
                !active && choice === recommended && "ring-2 ring-ring/40"
              )}
            >
              <span className="inline-flex items-center gap-1.5 text-sm font-semibold">
                <Icon className="size-3.5" />
                {label}
                {active ? " · recorded" : null}
              </span>
              <span
                className={cn(
                  "text-xs",
                  active ? "text-white/85" : "text-muted-foreground"
                )}
              >
                {hint}
              </span>
            </button>
          );
        })}
      </div>

      {recorded ? (
        <div className="flex flex-col gap-2 border-t pt-4 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-sm text-muted-foreground">
            Decision{" "}
            <span className="font-medium uppercase text-foreground">
              {recorded}
            </span>{" "}
            saved. Portfolio status updates when you go back.
          </p>
          <div className="flex flex-wrap gap-2">
            <Link
              href="/"
              className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
            >
              Back to portfolio
            </Link>
            {nextFeatureId ? (
              <Link
                href={`/features/${nextFeatureId}`}
                className={cn(
                  buttonVariants({ size: "sm" }),
                  "inline-flex gap-1.5"
                )}
              >
                Next: {nextFeatureName ?? nextFeatureId}
                <ArrowRight className="size-3.5" />
              </Link>
            ) : (
              <Button size="sm" disabled>
                Walkthrough complete
              </Button>
            )}
          </div>
        </div>
      ) : null}
    </section>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
