 * Env: RETRENCH_BASE_URL=https://<alb-or-ec2-host>
 * Memory: 128–256 MB · timeout: 10s · Node 20
 */
export async function handler() {
  const base = (process.env.RETRENCH_BASE_URL || "").replace(/\/$/, "");
  if (!base) {
    throw new Error("RETRENCH_BASE_URL is required");
  }

  const url = `${base}/api/features`;
  const res = await fetch(url, {
    method: "GET",
    headers: { Accept: "application/json" },
  });

  const text = await res.text();
  if (!res.ok) {
    throw new Error(`rollup failed ${res.status}: ${text.slice(0, 200)}`);
  }

  return {
    ok: true,
    status: res.status,
    bytes: text.length,
    at: new Date().toISOString(),
  };
}

