import { env } from "./config";

const BASE = () => env("NEATLOGS_BASE_URL", "https://app.neatlogs.com");

export type NeatlogsTraceSummary = {
  id: string;
  name?: string;
  status?: string;
  createdAt?: string;
  workflowName?: string;
};

/**
 * Public API read credential.
 * Neatlogs docs: SDK ingest keys (project API key used by checkout_agent)
 * do NOT authorize GET /api/v1/public/traces. Use a service-account token
 * (Settings → Service Accounts) as NEATLOGS_TOKEN.
 */
export function getNeatlogsReadToken(): string {
  return (
    env("NEATLOGS_TOKEN") ||
    env("NEATLOGS_SERVICE_ACCOUNT_TOKEN") ||
    env("NEATLOGS_API_KEY") ||
    env("NEATLOGS_PROJECT_API_KEY")
  );
}

export function hasNeatlogsCreds() {
  return Boolean(getNeatlogsReadToken());
}

export function hasNeatlogsServiceToken() {
  return Boolean(env("NEATLOGS_TOKEN") || env("NEATLOGS_SERVICE_ACCOUNT_TOKEN"));
}

export function hasNeatlogsIngestKey() {
  return Boolean(env("NEATLOGS_API_KEY") || env("NEATLOGS_PROJECT_API_KEY"));
}

async function neatlogsFetch(path: string) {
  const token = getNeatlogsReadToken();
  const projectId = env("NEATLOGS_PROJECT_ID");
  if (!token) {
    throw new Error(
      "Missing NEATLOGS_TOKEN (service-account) or NEATLOGS_API_KEY"
    );
  }

  const headers: Record<string, string> = {
    Authorization: `Bearer ${token}`,
    Accept: "application/json",
  };
  if (projectId) headers["x-project-id"] = projectId;

  const res = await fetch(`${BASE()}${path}`, {
    headers,
    cache: "no-store",
  });

  if (!res.ok) {
    const body = await res.text();
    if (res.status === 401 && !hasNeatlogsServiceToken()) {
      throw new Error(
        "neatlogs 401: ingest/project API key cannot read Public API. " +
          "Create Settings → Service Accounts token with observability:read, " +
          "set NEATLOGS_TOKEN in web/.env.local, restart npm run dev. " +
          `Raw: ${body.slice(0, 160)}`
      );
    }
    throw new Error(`neatlogs ${res.status}: ${body.slice(0, 200)}`);
  }
  return res.json();
}

/** Runtime truth — list recent traces (same list you see in app.neatlogs.com). */
export async function listTraces(limit = 10): Promise<NeatlogsTraceSummary[]> {
  const json = await neatlogsFetch(`/api/v1/public/traces?limit=${limit}`);
  const traces = json?.data?.traces ?? json?.traces ?? json?.data ?? [];
  const list = Array.isArray(traces) ? traces : [];
  return list.map((t: Record<string, unknown>) => ({
    id: String(t.id ?? t.traceId ?? t.trace_id ?? ""),
    name: t.name
      ? String(t.name)
      : t.workflowName
        ? String(t.workflowName)
        : t.workflow_name
          ? String(t.workflow_name)
          : undefined,
    status: t.status ? String(t.status) : undefined,
    createdAt: t.createdAt
      ? String(t.createdAt)
      : t.created_at
        ? String(t.created_at)
        : undefined,
    workflowName: t.workflowName
      ? String(t.workflowName)
      : t.workflow_name
        ? String(t.workflow_name)
        : undefined,
  }));
}

export async function getTrace(traceId: string) {
  return neatlogsFetch(`/api/v1/public/traces/${encodeURIComponent(traceId)}`);
}

export async function getProject() {
  return neatlogsFetch(`/api/v1/public/project`);
}

import { promises as fs } from "fs";
import path from "path";
import { env, useMockData } from "./config";
import { hasCfoCreds } from "./cfo";
import {
  getProject,
  hasNeatlogsIngestKey,
  hasNeatlogsServiceToken,
  listTraces,
} from "./neatlogs";

export type IntegrationStatus = {
  id: "neatlogs" | "entire" | "cfo" | "mock";
  label: string;
  ok: boolean;
  detail: string;
  nextStep?: string;
};

export type SetupReport = {
  mock: boolean;
  readyForLive: boolean;
  integrations: IntegrationStatus[];
  checkedAt: string;
};

async function entireStatus(): Promise<IntegrationStatus> {
  const repoRoot = path.resolve(
    /* turbopackIgnore: true */ process.cwd(),
    env("ENTIRE_REPO_PATH", "..")
  );
  const entireDir = path.join(/* turbopackIgnore: true */ repoRoot, ".entire");
  try {
    await fs.access(entireDir);
    const files = await walkJsonCount(entireDir, 20);
    if (files === 0) {
      return {
        id: "entire",
        label: "entire.io",
        ok: false,
        detail: `.entire exists at ${entireDir} but no checkpoint JSON yet`,
        nextStep:
          "Make a coding-agent commit after `entire enable --agent cursor`",
      };
    }
    return {
      id: "entire",
      label: "entire.io",
      ok: true,
      detail: `${files} checkpoint file(s) under .entire`,
    };
  } catch {
    return {
      id: "entire",
      label: "entire.io",
      ok: false,
      detail: "Entire not initialized in this repo",
      nextStep: "From repo root: entire enable --agent cursor",
    };
  }
}

async function walkJsonCount(dir: string, limit: number): Promise<number> {
  let count = 0;
  async function walk(current: string) {
    if (count >= limit) return;
    let entries;
    try {
      entries = await fs.readdir(current, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const full = path.join(current, e.name);
      if (e.isDirectory()) await walk(full);
      else if (e.isFile() && e.name.endsWith(".json")) count += 1;
      if (count >= limit) return;
    }
  }
  await walk(dir);
  return count;
}

async function neatlogsStatus(): Promise<IntegrationStatus> {
  const projectId = env("NEATLOGS_PROJECT_ID");
  if (!projectId) {
    return {
      id: "neatlogs",
      label: "neatlogs",
      ok: false,
      detail: "NEATLOGS_PROJECT_ID empty",
      nextStep: "Set project UUID d6852d79-66eb-4731-af1e-2e0895230d77",
    };
  }

  if (!hasNeatlogsServiceToken() && !hasNeatlogsIngestKey()) {
    return {
      id: "neatlogs",
      label: "neatlogs",
      ok: false,
      detail: "No neatlogs credentials in web/.env.local",
      nextStep:
        "Add NEATLOGS_TOKEN (service account for reads) + keep NEATLOGS_API_KEY for agent ingest",
    };
  }

  if (!hasNeatlogsServiceToken()) {
    return {
      id: "neatlogs",
      label: "neatlogs",
      ok: false,
      detail:
        "Ingest key present (agent traces work) but Public API reads need a service-account token",
      nextStep:
        "app.neatlogs.com → Settings → Service Accounts → mint token (observability:read) → NEATLOGS_TOKEN in web/.env.local → restart dev",
    };
  }

  try {
    await getProject();
    const traces = await listTraces(5);
    return {
      id: "neatlogs",
      label: "neatlogs",
      ok: true,
      detail: `Public API OK · ${traces.length} recent trace(s) · project ${projectId.slice(0, 8)}…`,
    };
  } catch (e) {
    return {
      id: "neatlogs",
      label: "neatlogs",
      ok: false,
      detail: e instanceof Error ? e.message : "neatlogs request failed",
      nextStep:
        "Re-mint service-account token bound to this project with observability:read",
    };
  }
}

function cfoStatus(): IntegrationStatus {
  if (!hasCfoCreds()) {
    return {
      id: "cfo",
      label: "cfo.ai",
      ok: false,
      detail:
        "No CFO_AI_ACCESS_TOKEN — using local deterministic unit-economics",
      nextStep: "Connect Ari MCP and set CFO_AI_ACCESS_TOKEN (+ optional ORG_ID)",
    };
  }
  return {
    id: "cfo",
    label: "cfo.ai",
    ok: true,
    detail: `Token set · MCP ${env("CFO_AI_MCP_URL", "https://api.cfo.ai/mcp")}`,
  };
}

export async function getSetupReport(): Promise<SetupReport> {
  const mock = useMockData();
  const [neatlogs, entire] = await Promise.all([
    neatlogsStatus(),
    entireStatus(),
  ]);
  const cfo = cfoStatus();
  const integrations: IntegrationStatus[] = [
    neatlogs,
    entire,
    cfo,
    {
      id: "mock",
      label: "data mode",
      ok: !mock,
      detail: mock
        ? "USE_MOCK_DATA=true — full demo story without live pulls"
        : "USE_MOCK_DATA=false — hybrid live enrichment on",
      nextStep: mock
        ? "Set USE_MOCK_DATA=false in web/.env.local after integrations are green"
        : undefined,
    },
  ];

  return {
    mock,
    readyForLive: neatlogs.ok && entire.ok,
    integrations,
    checkedAt: new Date().toISOString(),
  };
}

import { useMockData } from "./config";
import { inspectFeatureEconomics } from "./cfo";
import { latestCheckpoint } from "./entire";
import { getSetupReport } from "./integrations";
import { MOCK_FEATURES, mockInvestigate } from "./mock-data";
import { hasNeatlogsCreds, listTraces } from "./neatlogs";
import type { Feature, InvestigateBrief } from "./types";

export async function listFeatures(): Promise<{
  features: Feature[];
  sources: { neatlogs: boolean; entire: boolean; cfo: boolean; mock: boolean };
}> {
  const mock = useMockData();
  if (mock) {
    return {
      features: MOCK_FEATURES,
      sources: { neatlogs: false, entire: false, cfo: false, mock: true },
    };
  }

  const features = MOCK_FEATURES.map((f) => ({ ...f }));
  const setup = await getSetupReport();
  const neatlogsOk = setup.integrations.find((i) => i.id === "neatlogs")?.ok;
  const entireOk = setup.integrations.find((i) => i.id === "entire")?.ok;
  const cfoOk = setup.integrations.find((i) => i.id === "cfo")?.ok;

  if (hasNeatlogsCreds() && neatlogsOk) {
    try {
      const traces = await listTraces(5);
      const checkout = features.find((f) => f.id === "checkout-recovery");
      if (checkout && traces.length) {
        checkout.driver = `live traces: ${traces.length} recent`;
      }
    } catch {
      // sources already reflect failure via setup report
    }
  }

  return {
    features,
    sources: {
      neatlogs: Boolean(neatlogsOk),
      entire: Boolean(entireOk),
      cfo: Boolean(cfoOk),
      mock: false,
    },
  };
}

export async function getFeature(id: string): Promise<Feature | null> {
  const { features } = await listFeatures();
  return features.find((f) => f.id === id) ?? null;
}

export async function investigate(id: string): Promise<InvestigateBrief | null> {
  if (useMockData()) return mockInvestigate(id);

  const feature = await getFeature(id);
  if (!feature) return null;

  const base = mockInvestigate(id);
  if (!base) return null;

  const [change, money] = await Promise.all([
    latestCheckpoint(base.change.filesTouched),
    inspectFeatureEconomics({
      featureName: feature.name,
      successes: Math.round(feature.attempts7d * feature.successRate),
      failures: Math.round(feature.attempts7d * (1 - feature.successRate)),
      valuePerSuccess: feature.valuePerSuccess,
      costPerSuccess: feature.costPerSuccess,
      costPerFailure: feature.costPerFailure,
    }),
  ]);

  let runtime = {
    ...base.runtime,
    evidenceSpans: [
      ...base.runtime.evidenceSpans,
      "Story evidence (demo scenario) — live neatlogs IDs appear below when Public API is authorized",
    ],
  };

  if (hasNeatlogsCreds()) {
    try {
      const traces = await listTraces(10);
      const liveIds = traces.map((t) => t.id).filter(Boolean);
      if (liveIds.length) {
        runtime = {
          source: "neatlogs",
          successRate: feature.successRate,
          costPerSuccess: feature.costPerSuccess,
          openIncidents: base.runtime.openIncidents,
          evidenceSpans: [
            `LIVE from neatlogs Public API · ${liveIds.length} recent trace(s)`,
            ...traces.slice(0, 5).map((t) => {
              const label = t.name || t.workflowName || "trace";
              const st = t.status ? ` · ${t.status}` : "";
              return `${label} · ${t.id}${st}`;
            }),
            "Portfolio KPIs (62% / $1.40) remain the demo unit-economics story until Watchdog rollups land",
          ],
          traceIds: liveIds,
        };
      } else {
        runtime = {
          ...runtime,
          evidenceSpans: [
            ...runtime.evidenceSpans,
            "neatlogs Public API OK — no traces returned yet (run demo/agents/checkout_agent.py)",
          ],
        };
      }
    } catch (e) {
      runtime = {
        ...runtime,
        evidenceSpans: [
          ...runtime.evidenceSpans,
          e instanceof Error ? e.message : "neatlogs error: unknown",
        ],
      };
    }
  }

  return {
    ...base,
    feature,
    runtime,
    change: {
      source: "entire.io",
      ...change,
    },
    money,
  };
}

export function decideKeepFixKill(brief: InvestigateBrief): "keep" | "fix" | "kill" {
  if (brief.feature.status === "healthy" && brief.feature.netContribDelta >= 0) {
    return "keep";
  }
  if (
    brief.money.lostContributionPerDay &&
    brief.money.lostContributionPerDay > 3000
  ) {
    return brief.change.commit ? "fix" : "kill";
  }
  if (brief.feature.status === "regress") return "fix";
  return brief.decision;
}

/**
 * Probe neatlogs Public API using web/.env.local (no secrets printed).
 * Usage: node scripts/probe-neatlogs.mjs
 */
import { readFileSync } from "fs";
import { resolve, dirname } from "path";
import { fileURLToPath } from "url";

