                      );
                    })}
                  </ul>
                </div>
              ) : (
                <ul className="space-y-2 text-sm text-muted-foreground">
                  {runtime.evidenceSpans.map((s) => (
                    <li key={s} className="flex gap-2">
                      <span className="mt-1.5 size-1.5 shrink-0 rounded-full bg-primary" />
                      {s}
