} from "@/lib/decisions";

function money(n: number) {
  return `$${Math.abs(n).toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
}

const actions: {
  choice: DecisionChoice;
  label: string;
  hint: (atRisk: number) => string;
  icon: typeof Check;
  className: string;
}[] = [
  {
    choice: "keep",
    label: "Keep",
    hint: () => "Accept current economics — leave autonomy on",
    icon: Check,
    className: "bg-emerald-700 text-white hover:bg-emerald-700/90",
  },
  {
    choice: "fix",
    label: "Fix",
    hint: (atRisk) =>
      atRisk
        ? `Restore retries — claw back ~${money(atRisk)}/day`
        : "Ship the brief — restore margin",
    icon: Wrench,
    className: "bg-amber-600 text-white hover:bg-amber-600/90",
  },
  {
    choice: "kill",
    label: "Kill",
    hint: () => "Pause the agent — stop OpEx on a losing feature",
    icon: Ban,
    className: "bg-red-700 text-white hover:bg-red-700/90",
  },
];

export function DecisionActions({
  featureId,
  recommended,
  nextFeatureId,
  nextFeatureName,
  atRiskPerDay = 0,
}: {
  featureId: string;
  recommended: DecisionChoice;
  nextFeatureId?: string;
  nextFeatureName?: string;
  atRiskPerDay?: number;
}) {
  const [recorded, setRecorded] = useState<DecisionChoice | null>(null);

  useEffect(() => {
    setRecorded(readDecisions()[featureId]?.choice ?? null);
  }, [featureId]);

  function choose(choice: DecisionChoice) {
    writeDecision(featureId, choice);
    setRecorded(choice);
  }

  return (
    <section className="retrench-enter retrench-enter-delay-3 space-y-4 rounded-2xl border bg-card p-5 shadow-sm sm:p-6">
      <div>
        <h2 className="text-base font-semibold tracking-tight">Your call</h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Retrench recommends{" "}
          <span className="font-medium text-foreground uppercase">
            {recommended}
          </span>
          {atRiskPerDay ? (
            <>
              {" "}
              because ~{money(atRiskPerDay)}/day of contribution is on the line.
            </>
          ) : (
            <> — confirm to record the portfolio decision.</>
          )}
        </p>
      </div>

      <div className="grid gap-2 sm:grid-cols-3">
        {actions.map(({ choice, label, hint, icon: Icon, className }) => {
          const active = recorded === choice;
          return (
            <button
              key={choice}
              type="button"
              onClick={() => choose(choice)}
              className={cn(
                "flex flex-col items-start gap-1 rounded-xl border px-4 py-3 text-left transition",
                active ? className : "bg-background hover:bg-muted/60",
                !active && choice === recommended && "ring-2 ring-ring/40"
              )}
            >
              <span className="inline-flex items-center gap-1.5 text-sm font-semibold">
                <Icon className="size-3.5" />
                {label}
                {active ? " · recorded" : null}
              </span>
              <span
                className={cn(
                  "text-xs",
                  active ? "text-white/85" : "text-muted-foreground"
                )}
              >
                {hint(atRiskPerDay)}
              </span>
            </button>
          );
        })}
      </div>

      {recorded ? (
        <div className="flex flex-col gap-2 border-t pt-4 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-sm text-muted-foreground">
            Decision{" "}
            <span className="font-medium uppercase text-foreground">
              {recorded}
            </span>{" "}
            saved
            {recorded === "fix"
              ? " — hand the brief to eng / coding agent next."
              : recorded === "kill"
                ? " — pause checkout_agent autonomy in prod."
                : " — no change to prod."}
          </p>
          <div className="flex flex-wrap gap-2">
            <Link
              href="/"
              className={cn(buttonVariants({ variant: "outline", size: "sm" }))}
            >
              Back to portfolio
            </Link>
            {nextFeatureId ? (
              <Link
                href={`/features/${nextFeatureId}`}
                className={cn(
                  buttonVariants({ size: "sm" }),
                  "inline-flex gap-1.5"
                )}
              >
                Next: {nextFeatureName ?? nextFeatureId}
                <ArrowRight className="size-3.5" />
              </Link>
            ) : (
              <Button size="sm" disabled>
                Walkthrough complete
              </Button>
            )}
          </div>
        </div>
      ) : null}
    </section>
  );
}

import { promises as fs } from "fs";
import path from "path";
import type { DecisionChoice } from "./decisions";

export type WatchdogState = {
  active: boolean;
  startedAt: string;
  lastCheckAt?: string;
  ok?: boolean;
  detail: string;
  targetSuccessRate: number;
};

export type FeatureAgentState = {
  featureId: string;
  featureName: string;
  decision: DecisionChoice;
  reason: string;
  fixBrief?: string;
  paused: boolean;
  cliff: boolean;
  liveSuccessRate?: number;
  errorTraces: number;
  okTraces: number;
  atRiskPerDay?: number;
  decidedAt: string;
  watchdog?: WatchdogState;
};

export type AgentTickRun = {
  at: string;
  featuresChecked: number;
  cliffs: number;
  decisions: DecisionChoice[];
  summary: string;
};

export type ControlAgentState = {
  version: 1;
  updatedAt: string;
  lastTickAt?: string;
  features: Record<string, FeatureAgentState>;
  recentTicks: AgentTickRun[];
  briefs: { featureId: string; path: string; at: string }[];
};

const STATE_DIR = () =>
  path.join(/* turbopackIgnore: true */ process.cwd(), ".retrench");
const STATE_FILE = () => path.join(STATE_DIR(), "control-agent-state.json");
const BRIEFS_DIR = () => path.join(STATE_DIR(), "briefs");

function emptyState(): ControlAgentState {
  return {
    version: 1,
    updatedAt: new Date().toISOString(),
    features: {},
    recentTicks: [],
    briefs: [],
  };
}

export async function readAgentState(): Promise<ControlAgentState> {
  try {
    const raw = await fs.readFile(STATE_FILE(), "utf8");
    return JSON.parse(raw) as ControlAgentState;
  } catch {
    return emptyState();
  }
}

export async function writeAgentState(
  state: ControlAgentState
): Promise<ControlAgentState> {
  await fs.mkdir(STATE_DIR(), { recursive: true });
  const next = { ...state, updatedAt: new Date().toISOString() };
  await fs.writeFile(STATE_FILE(), JSON.stringify(next, null, 2), "utf8");
  return next;
}

export async function writeFixBrief(input: {
  featureId: string;
  featureName: string;
  brief: string;
  decision: DecisionChoice;
  traceIds: string[];
}): Promise<string> {
  await fs.mkdir(BRIEFS_DIR(), { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const file = path.join(BRIEFS_DIR(), `${input.featureId}-${stamp}.md`);
  const body = `# Fix brief — ${input.featureName}

**Decision:** ${input.decision.toUpperCase()}  
**Generated:** ${new Date().toISOString()}  
**For:** coding agent (Cursor / Claude Code / Codex)

## Brief

${input.brief}

## neatlogs evidence

${input.traceIds.map((id) => `- \`${id}\``).join("\n") || "- (none)"}

## Acceptance (Watchdog)

- Success rate ≥ 80% on recent checkout_agent traces  
- Cost / success ≤ $0.80 (modeled)  
- Failure class cleared in neatlogs  

Hand this file to your coding agent, apply the patch, commit (Entire checkpoint), then run Watchdog.
`;
  await fs.writeFile(file, body, "utf8");
  return file;
}

import {
  readAgentState,
  writeAgentState,
  writeFixBrief,
  type ControlAgentState,
  type FeatureAgentState,
} from "./agent-store";
import type { DecisionChoice } from "./decisions";
import {
  decideKeepFixKill,
  investigate,
  listFeatures,
} from "./retrench";
import { listFeatureTraces } from "./neatlogs";

const ERROR_CLIFF = 0.35; // >35% ERROR in recent sample → cliff
const WATCHDOG_TARGET = 0.8;

export type TickResult = {
  state: ControlAgentState;
  tick: ControlAgentState["recentTicks"][number];
};

/**
 * One autonomous control-agent cycle:
 * Watch → Investigate → Decide → Act → (Watchdog if verifying)
 */
export async function runControlAgentTick(): Promise<TickResult> {
  const { features } = await listFeatures();
  const state = await readAgentState();
  const decisions: DecisionChoice[] = [];
  let cliffs = 0;

  for (const feature of features) {
    const brief = await investigate(feature.id);
    if (!brief) continue;

    const traces = brief.runtime.liveTraces ?? [];
    const ok = traces.filter((t) => (t.status || "").toUpperCase() === "OK")
      .length;
    const err = traces.filter((t) => (t.status || "").toUpperCase() === "ERROR")
      .length;
    const liveRate =
      traces.length > 0 ? ok / traces.length : brief.runtime.successRate;
    const cliff =
      feature.status === "regress" ||
      (traces.length > 0 && err / traces.length >= ERROR_CLIFF) ||
      liveRate < WATCHDOG_TARGET;

    if (cliff) cliffs += 1;

    const decision = decideKeepFixKill({
      ...brief,
      decision: brief.decision,
    });
    decisions.push(decision);

    let fixBriefPath: string | undefined;
    let paused = state.features[feature.id]?.paused ?? false;

    if (decision === "fix" && cliff) {
      fixBriefPath = await writeFixBrief({
        featureId: feature.id,
        featureName: feature.name,
        brief: brief.fixBrief,
        decision,
        traceIds: brief.runtime.traceIds,
      });
      state.briefs.unshift({
        featureId: feature.id,
        path: fixBriefPath,
        at: new Date().toISOString(),
      });
      state.briefs = state.briefs.slice(0, 20);
    }

    if (decision === "kill" && cliff) {
      paused = true;
    }
    if (decision === "keep") {
      paused = false;
    }

    const existing = state.features[feature.id];
    let watchdog = existing?.watchdog;

    if (decision === "fix" && cliff) {
      watchdog = {
        active: true,
        startedAt: new Date().toISOString(),
        targetSuccessRate: WATCHDOG_TARGET,
        detail: "Watchdog armed — waiting for post-fix neatlogs verification",
      };
    }

    if (watchdog?.active) {
      watchdog = await runWatchdogCheck(feature.id, watchdog);
    }

    const entry: FeatureAgentState = {
      featureId: feature.id,
      featureName: feature.name,
      decision,
      reason: brief.runtime.soWhat ?? brief.fixBrief,
      fixBrief: brief.fixBrief,
      paused,
      cliff,
      liveSuccessRate: liveRate,
      errorTraces: err,
      okTraces: ok,
      atRiskPerDay: brief.money.lostContributionPerDay,
      decidedAt: new Date().toISOString(),
      watchdog,
    };
    state.features[feature.id] = entry;
  }

  const tick = {
    at: new Date().toISOString(),
    featuresChecked: features.length,
    cliffs,
    decisions,
    summary:
      cliffs > 0
        ? `Detected ${cliffs} cliff(s). Decisions: ${decisions.join(", ") || "none"}.`
        : `No cliffs. Portfolio healthy across ${features.length} feature(s).`,
  };
  state.lastTickAt = tick.at;
  state.recentTicks = [tick, ...state.recentTicks].slice(0, 30);

  const saved = await writeAgentState(state);
  return { state: saved, tick };
}

async function runWatchdogCheck(
  featureId: string,
  watchdog: NonNullable<FeatureAgentState["watchdog"]>
) {
  const hint =
    featureId === "checkout-recovery" ? "checkout-recovery" : featureId;
  try {
    const traces = await listFeatureTraces(hint, 10);
    const ok = traces.filter((t) => (t.status || "").toUpperCase() === "OK")
      .length;
    const rate = traces.length ? ok / traces.length : 0;
    const passed = traces.length > 0 && rate >= watchdog.targetSuccessRate;
    return {
      ...watchdog,
      lastCheckAt: new Date().toISOString(),
      ok: passed,
      active: !passed,
      detail: passed
        ? `Watchdog PASSED — ${(rate * 100).toFixed(0)}% OK on ${traces.length} recent traces (≥ ${(watchdog.targetSuccessRate * 100).toFixed(0)}%)`
        : `Watchdog WAITING — ${(rate * 100).toFixed(0)}% OK on ${traces.length} traces (need ≥ ${(watchdog.targetSuccessRate * 100).toFixed(0)}%)`,
    };
  } catch (e) {
    return {
      ...watchdog,
      lastCheckAt: new Date().toISOString(),
      ok: false,
      detail: `Watchdog error: ${e instanceof Error ? e.message : "unknown"}`,
    };
  }
}

export async function runWatchdogOnly(featureId: string) {
  const state = await readAgentState();
  const current = state.features[featureId];
  if (!current) {
    throw new Error(`No control-agent state for ${featureId} — run a tick first`);
  }
  const watchdog = current.watchdog ?? {
    active: true,
    startedAt: new Date().toISOString(),
    targetSuccessRate: WATCHDOG_TARGET,
    detail: "Watchdog started manually",
  };
  current.watchdog = await runWatchdogCheck(featureId, {
    ...watchdog,
    active: true,
  });
  state.features[featureId] = current;
  return writeAgentState(state);
}

