    neatlogsCopilot?: string;
    retrenchOncall?: string;
  };
};

export async function readOncallInbox(): Promise<OncallInbox | null> {
  try {
    const raw = await fs.readFile(
      path.join(retrenchStateDir(), "inbox", "latest.json"),
      "utf8"
    );
    return JSON.parse(raw) as OncallInbox;
  } catch {
    return null;
  }
}

export async function readOncallState(): Promise<OncallState | null> {
  try {
    const raw = await fs.readFile(
      path.join(retrenchStateDir(), "oncall-state.json"),
      "utf8"
    );
    return JSON.parse(raw) as OncallState;
  } catch {
    return null;
  }
}

