"use client";

import { useEffect, useState, useTransition } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

type Payload = {
  inbox: {
    at: string;
    message: string;
    decision?: string;
    cliff?: boolean;
    ok?: number;
    err?: number;
    rate?: number;
    briefPath?: string | null;
    paused?: boolean;
    watchdog?: string;
    workflow?: string;
  } | null;
  state: {
    differentiation?: {
      neatlogsCopilot?: string;
      retrenchOncall?: string;
    };
    updatedAt?: string;
  } | null;
  product: string;
};

export function OncallInbox() {
  const [data, setData] = useState<Payload | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const load = () => {
    start(async () => {
      try {
        const res = await fetch("/api/oncall", { cache: "no-store" });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        setData(await res.json());
        setError(null);
      } catch (e) {
        setError(e instanceof Error ? e.message : "failed");
      }
    });
  };

  useEffect(() => {
    load();
    const id = setInterval(load, 15_000);
    return () => clearInterval(id);
  }, []);

  const inbox = data?.inbox;
  const decision = inbox?.decision?.toUpperCase();

  return (
    <div className="mx-auto flex w-full max-w-2xl flex-col gap-8 px-4 py-12 sm:px-6">
      <header className="space-y-3">
        <p className="text-xs font-medium uppercase tracking-[0.2em] text-teal-800/70">
          Retrench oncall
        </p>
        <h1 className="font-serif text-4xl font-medium tracking-tight text-stone-900 sm:text-5xl">
          Your AI features have an on-call agent.
        </h1>
        <p className="max-w-xl text-base leading-relaxed text-stone-600">
          You do not sign into neatlogs, Entire, and cfo.ai to babysit Features.
          Oncall watches runtime, joins the last change, prices fix vs kill, then
          acts — and leaves you one message.
        </p>
      </header>

      <section className="space-y-3 border-t border-stone-200 pt-6">
        <div className="flex items-center justify-between gap-3">
          <h2 className="text-sm font-semibold text-stone-900">
            Last message from oncall
          </h2>
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={pending}
            onClick={load}
          >
            {pending ? "Refreshing…" : "Refresh"}
          </Button>
        </div>

        {error ? (
          <p className="text-sm text-red-700">{error}</p>
        ) : null}

        {!inbox ? (
          <div className="space-y-3 rounded-lg bg-stone-100/80 px-4 py-5 text-sm text-stone-700">
            <p className="font-medium text-stone-900">No ticks yet.</p>
            <p>
              Run the watched feature, then the oncall agent (no dashboard
              required):
            </p>
            <pre className="overflow-x-auto rounded-md bg-stone-900 px-3 py-3 text-xs text-stone-100">
{`python demo/agents/checkout_agent.py
AGENT_ONCE=1 python demo/agents/retrench_oncall.py`}
            </pre>
          </div>
        ) : (
          <article className="space-y-4">
            <div className="flex flex-wrap items-center gap-2">
              {decision ? (
                <Badge
                  className={
                    decision === "FIX"
                      ? "bg-amber-600"
                      : decision === "KILL"
                        ? "bg-red-700"
                        : "bg-teal-800"
                  }
                >
                  {decision}
                </Badge>
              ) : null}
              {inbox.paused ? <Badge variant="secondary">PAUSED</Badge> : null}
              {inbox.cliff ? <Badge variant="outline">cliff</Badge> : null}
              <span className="text-xs text-stone-500">{inbox.at}</span>
            </div>
            <pre className="whitespace-pre-wrap rounded-lg border border-stone-200 bg-white px-4 py-4 font-mono text-[13px] leading-relaxed text-stone-800 shadow-sm">
              {inbox.message}
            </pre>
            {inbox.briefPath ? (
              <p className="text-xs text-stone-500">
                Fix brief on disk:{" "}
                <code className="text-stone-800">{inbox.briefPath}</code>
              </p>
            ) : null}
          </article>
        )}
      </section>

      <section className="space-y-3 border-t border-stone-200 pt-6 text-sm text-stone-600">
        <h2 className="text-sm font-semibold text-stone-900">
          Not Neatlogs Copilot
        </h2>
        <ul className="list-disc space-y-2 pl-5">
          <li>
            <span className="font-medium text-stone-800">Copilot</span> —
            analyzes traces, detections, prompts inside neatlogs. Helps you
            debug. Does not modify your app or deploy.
          </li>
          <li>
            <span className="font-medium text-stone-800">Retrench oncall</span> —{" "}
            {data?.state?.differentiation?.retrenchOncall ||
              "autonomous watch → Entire cause → cfo $ → pause / fix brief → watchdog, without you in three UIs."}
          </li>
        </ul>
        <p className="text-xs text-stone-500">{data?.product}</p>
      </section>
    </div>
  );
}

