"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { Bell, ArrowRight } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { cn } from "@/lib/utils";

type Inbox = {
  at: string;
  message: string;
  decision?: string;
  cliff?: boolean;
  paused?: boolean;
  workflow?: string;
  briefPath?: string | null;
  watchdog?: string;
};

/** User-lens strip: what oncall already decided for you (shadcn). */
export function OncallBanner() {
  const [inbox, setInbox] = useState<Inbox | null>(null);
  const [pending, start] = useTransition();

  const load = () => {
    start(async () => {
      try {
        const res = await fetch("/api/oncall", { cache: "no-store" });
        if (!res.ok) return;
        const json = await res.json();
        setInbox(json.inbox ?? null);
      } catch {
        /* ignore */
      }
    });
  };

  useEffect(() => {
    load();
    const id = setInterval(load, 20_000);
    return () => clearInterval(id);
  }, []);

  if (!inbox) {
    return (
      <Alert className="retrench-enter border-dashed">
        <Bell className="size-4" />
        <AlertTitle>Oncall hasn&apos;t messaged you yet</AlertTitle>
        <AlertDescription className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <span>
            You don&apos;t babysit three platforms. Run a tick on{" "}
            <Link href="/agent" className="font-medium underline-offset-4 hover:underline">
              Oncall
            </Link>{" "}
            (or{" "}
            <code className="rounded bg-muted px-1 font-mono text-xs">
              python demo/agents/retrench_oncall.py
            </code>
            ) and your keep / fix / kill lands here.
          </span>
          <Link
            href="/agent"
            className={cn(buttonVariants({ size: "sm" }), "shrink-0 gap-1.5")}
          >
            Open oncall
            <ArrowRight className="size-3.5" />
          </Link>
        </AlertDescription>
      </Alert>
    );
  }

  const decision = (inbox.decision || "").toUpperCase();

  return (
    <Card className="retrench-enter border-primary/15 shadow-sm">
      <CardHeader className="flex flex-row items-start justify-between gap-4 space-y-0 pb-3">
        <div className="space-y-1.5">
          <CardDescription className="flex items-center gap-1.5">
            <Bell className="size-3.5" />
            Message from oncall · you didn&apos;t have to sign in
          </CardDescription>
          <CardTitle className="text-lg">
            {inbox.workflow || "Feature"} —{" "}
            <span className="text-muted-foreground">
              {decision || "update"}
            </span>
          </CardTitle>
        </div>
        <div className="flex flex-wrap items-center gap-1.5">
          {decision ? (
            <Badge
              className={
                decision === "FIX"
                  ? "rounded-md bg-amber-600 text-white hover:bg-amber-600"
                  : decision === "KILL"
                    ? "rounded-md bg-red-700 text-white hover:bg-red-700"
                    : "rounded-md bg-emerald-700 text-white hover:bg-emerald-700"
              }
            >
              {decision}
            </Badge>
          ) : null}
          {inbox.paused ? (
            <Badge className="rounded-md bg-zinc-700 text-white hover:bg-zinc-700">
              paused
            </Badge>
          ) : null}
          {inbox.cliff ? (
            <Badge variant="outline" className="rounded-md">
              cliff
            </Badge>
          ) : null}
          <Button
            type="button"
            variant="ghost"
            size="sm"
            disabled={pending}
            onClick={load}
          >
            Refresh
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-3">
        <pre className="max-h-48 overflow-auto whitespace-pre-wrap rounded-lg border bg-muted/30 p-3 font-mono text-xs leading-relaxed text-foreground">
          {inbox.message}
        </pre>
        <div className="flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground">
          <span>{new Date(inbox.at).toLocaleString("en-US")}</span>
          <Link
            href="/agent"
            className={cn(
              buttonVariants({ variant: "outline", size: "sm" }),
              "gap-1.5"
            )}
          >
            Full oncall status
            <ArrowRight className="size-3.5" />
          </Link>
        </div>
      </CardContent>
    </Card>
  );
}

