"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import {
  Bell,
  Bot,
  Play,
  RefreshCw,
  ShieldCheck,
  Terminal,
} from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";

type FeatureState = {
  featureId: string;
  featureName: string;
  decision: string;
  reason: string;
  paused: boolean;
  cliff: boolean;
  liveSuccessRate?: number;
  errorTraces: number;
  okTraces: number;
  atRiskPerDay?: number;
  watchdog?: {
    active: boolean;
    ok?: boolean;
    detail: string;
  };
};

type AgentState = {
  lastTickAt?: string;
  features: Record<string, FeatureState>;
  recentTicks: {
    at: string;
    featuresChecked: number;
    cliffs: number;
    summary: string;
  }[];
};

type OncallPayload = {
  inbox: {
    at: string;
    message: string;
    decision?: string;
    cliff?: boolean;
    paused?: boolean;
    workflow?: string;
    briefPath?: string | null;
    watchdog?: string;
    ok?: number;
    err?: number;
    rate?: number;
  } | null;
  state: {
    updatedAt?: string;
    decision?: string;
    watchdog?: string;
    briefPath?: string | null;
    paused?: boolean;
    differentiation?: {
      neatlogsCopilot?: string;
      retrenchOncall?: string;
    };
  } | null;
  product?: string;
};

export default function AgentPage() {
  const [state, setState] = useState<AgentState | null>(null);
  const [oncall, setOncall] = useState<OncallPayload | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    const [agentRes, oncallRes] = await Promise.all([
      fetch("/api/agent/state", { cache: "no-store" }),
      fetch("/api/oncall", { cache: "no-store" }),
    ]);
    setState((await agentRes.json()) as AgentState);
    setOncall((await oncallRes.json()) as OncallPayload);
  }, []);

  useEffect(() => {
    void refresh();
    const id = setInterval(() => void refresh(), 15_000);
    return () => clearInterval(id);
  }, [refresh]);

  async function runTick() {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/agent/tick", { method: "POST" });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "tick failed");
      setState(json.state);
      await refresh();
    } catch (e) {
      setError(e instanceof Error ? e.message : "tick failed");
    } finally {
      setBusy(false);
    }
  }

  async function runWatchdog(featureId: string) {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/agent/watchdog", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ featureId }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "watchdog failed");
      setState(json.state);
    } catch (e) {
      setError(e instanceof Error ? e.message : "watchdog failed");
    } finally {
      setBusy(false);
    }
  }

  const features = Object.values(state?.features ?? {});
  const inbox = oncall?.inbox;
  const decision = (inbox?.decision || "").toUpperCase();

  return (
    <div className="mx-auto flex w-full max-w-5xl flex-col gap-8 px-4 py-10 sm:px-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div className="space-y-2">
          <Badge className="rounded-md bg-primary text-primary-foreground hover:bg-primary">
            your oncall agent
          </Badge>
          <h1 className="text-3xl font-semibold tracking-tight">
            What oncall did for you
          </h1>
          <p className="max-w-2xl text-muted-foreground">
            Neatlogs Copilot helps you debug traces in their UI. Retrench oncall
            runs without you — watches neatlogs, joins Entire, prices fix vs
            kill, then pauses or writes a fix brief. This page is your inbox,
            not a second observability console.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button
            onClick={() => void runTick()}
            disabled={busy}
            className="gap-1.5"
          >
            <Play className="size-3.5" />
            Run tick
          </Button>
          <Button
            variant="outline"
            onClick={() => void refresh()}
            disabled={busy}
            className="gap-1.5"
          >
            <RefreshCw className="size-3.5" />
            Refresh
          </Button>
        </div>
      </div>

      {error ? (
        <Alert variant="destructive">
          <AlertTitle>Tick failed</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      ) : null}

      <Card className="shadow-sm">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Bell className="size-4" />
            Latest message
          </CardTitle>
          <CardDescription>
            Same message oncall writes to{" "}
            <code className="font-mono text-xs">.retrench/inbox/</code> and
            Slack (if configured)
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {!inbox ? (
            <Alert>
              <Terminal className="size-4" />
              <AlertTitle>No oncall message yet</AlertTitle>
              <AlertDescription className="space-y-2">
                <p>
                  Click <strong>Run tick</strong>, or on EC2 / locally:
                </p>
                <pre className="overflow-x-auto rounded-md border bg-muted/40 p-3 font-mono text-xs">
{`AGENT_ONCE=1 python demo/agents/retrench_oncall.py`}
                </pre>
              </AlertDescription>
            </Alert>
          ) : (
            <>
              <div className="flex flex-wrap items-center gap-1.5">
                {decision ? (
                  <Badge
                    className={
                      decision === "FIX"
                        ? "rounded-md bg-amber-600 text-white hover:bg-amber-600"
                        : decision === "KILL"
                          ? "rounded-md bg-red-700 text-white hover:bg-red-700"
                          : "rounded-md bg-emerald-700 text-white hover:bg-emerald-700"
                    }
                  >
                    {decision}
                  </Badge>
                ) : null}
                {inbox.paused ? (
                  <Badge className="rounded-md bg-zinc-700 text-white hover:bg-zinc-700">
                    paused
                  </Badge>
                ) : null}
                {inbox.cliff ? (
                  <Badge variant="outline" className="rounded-md">
                    cliff
                  </Badge>
                ) : null}
                <span className="text-xs text-muted-foreground">
                  {new Date(inbox.at).toLocaleString("en-US")}
                </span>
              </div>
              <pre className="whitespace-pre-wrap rounded-xl border bg-muted/20 p-4 font-mono text-xs leading-relaxed">
                {inbox.message}
              </pre>
              {inbox.briefPath ? (
                <p className="text-xs text-muted-foreground">
                  Fix brief:{" "}
                  <code className="font-mono text-foreground">
                    {inbox.briefPath}
                  </code>
                </p>
              ) : null}
              {inbox.watchdog ? (
                <p className="text-xs text-muted-foreground">
                  Watchdog: {inbox.watchdog}
                </p>
              ) : null}
            </>
          )}
        </CardContent>
      </Card>

      <Alert className="border-dashed">
        <Bot className="size-4" />
        <AlertTitle>Not Neatlogs Copilot</AlertTitle>
        <AlertDescription>
          {oncall?.state?.differentiation?.retrenchOncall ||
            oncall?.product ||
            "Copilot analyzes traces inside neatlogs and cannot modify your app. Oncall acts across neatlogs + Entire + cfo formulas."}
        </AlertDescription>
      </Alert>

      <div className="grid gap-3 sm:grid-cols-3">
        <Card className="shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription>Last API tick</CardDescription>
            <CardTitle className="text-base font-medium">
              {state?.lastTickAt
                ? new Date(state.lastTickAt).toLocaleString("en-US")
                : "Not run yet"}
            </CardTitle>
          </CardHeader>
        </Card>
        <Card className="shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription>Features tracked</CardDescription>
            <CardTitle className="text-3xl tracking-tight">
              {features.length || (inbox ? 1 : 0)}
            </CardTitle>
          </CardHeader>
        </Card>
        <Card className="shadow-sm">
          <CardHeader className="pb-2">
            <CardDescription>Open cliffs</CardDescription>
            <CardTitle className="text-3xl tracking-tight">
              {features.filter((f) => f.cliff).length ||
                (inbox?.cliff ? 1 : 0)}
            </CardTitle>
          </CardHeader>
        </Card>
      </div>

      <Card className="shadow-sm">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <Bot className="size-4" />
            Feature decisions
          </CardTitle>
          <CardDescription>
            Autonomous keep / fix / kill from the latest tick
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          {features.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              Run a tick to sync portfolio decisions, or rely on{" "}
              <code className="font-mono text-xs">retrench_oncall.py</code> on
              EC2 for the user message above.
            </p>
          ) : (
            features.map((f) => (
              <div key={f.featureId} className="rounded-xl border p-4 text-sm">
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <div className="font-medium">
                    <Link
                      href={`/features/${f.featureId}`}
                      className="underline-offset-4 hover:underline"
                    >
                      {f.featureName}
                    </Link>
                  </div>
                  <div className="flex flex-wrap gap-1.5">
                    {f.cliff ? (
                      <Badge className="rounded-md bg-red-600 text-white hover:bg-red-600">
                        cliff
                      </Badge>
                    ) : null}
                    {f.paused ? (
                      <Badge className="rounded-md bg-zinc-600 text-white hover:bg-zinc-600">
                        paused
                      </Badge>
                    ) : null}
                    <Badge className="rounded-md uppercase">{f.decision}</Badge>
                  </div>
                </div>
                <p className="mt-2 text-muted-foreground">{f.reason}</p>
                <p className="mt-2 text-xs text-muted-foreground">
                  Live sample: {f.okTraces} OK / {f.errorTraces} ERROR
                  {f.liveSuccessRate != null
                    ? ` · ${(f.liveSuccessRate * 100).toFixed(0)}%`
                    : ""}
                  {f.atRiskPerDay
                    ? ` · ~$${f.atRiskPerDay.toLocaleString("en-US")}/day at risk`
                    : ""}
                </p>
                {f.watchdog ? (
                  <div className="mt-3 flex flex-col gap-2 rounded-lg border bg-muted/20 p-3 sm:flex-row sm:items-center sm:justify-between">
                    <p className="text-xs text-muted-foreground">
                      {f.watchdog.detail}
                    </p>
                    <Button
                      size="sm"
                      variant="outline"
                      className="gap-1.5"
                      disabled={busy}
                      onClick={() => void runWatchdog(f.featureId)}
                    >
                      <ShieldCheck className="size-3.5" />
                      Run Watchdog
                    </Button>
                  </div>
                ) : null}
              </div>
            ))
          )}
        </CardContent>
      </Card>

      <Card className="shadow-sm">
        <CardHeader>
          <CardTitle className="text-base">Recent ticks</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2 text-sm text-muted-foreground">
          {(state?.recentTicks ?? []).slice(0, 8).map((t) => (
            <div
              key={t.at}
              className="flex flex-col gap-0.5 rounded-lg border px-3 py-2 sm:flex-row sm:justify-between"
            >
              <span>{t.summary}</span>
              <span className="shrink-0 text-xs">
                {new Date(t.at).toLocaleString("en-US")}
              </span>
            </div>
          ))}
          {(state?.recentTicks ?? []).length === 0 ? (
            <p>No API tick history yet — oncall Python may still have messaged you above.</p>
          ) : null}
        </CardContent>
      </Card>

      <Separator />

      <p className="text-xs text-muted-foreground">
        EC2 product process:{" "}
        <code className="font-mono">retrench_oncall.py</code> via systemd.{" "}
        <Link
          href="/"
          className={cn(
            buttonVariants({ variant: "link", size: "sm" }),
            "h-auto p-0"
          )}
        >
          Back to portfolio
        </Link>
      </p>
    </div>
  );
}

