/** Keep portfolio banner + /agent inbox in sync with API ticks (user lens). */
async function syncOncallInbox(state: ControlAgentState, summary: string) {
  const primary =
    Object.values(state.features).find((f) => f.cliff) ||
    Object.values(state.features)[0];
  if (!primary) return;

  const message = [
    `Retrench oncall - ${primary.featureId}`,
    `Decision: ${primary.decision.toUpperCase()}  |  live OK ${primary.okTraces}/${primary.okTraces + primary.errorTraces}${
      primary.liveSuccessRate != null
        ? ` (${(primary.liveSuccessRate * 100).toFixed(0)}%)`
        : ""
    }`,
    primary.reason,
    primary.paused
      ? "Action: PAUSED feature flag under .retrench/paused/"
      : null,
    primary.watchdog ? `Watchdog: ${primary.watchdog.detail}` : null,
    summary,
    "You did not need to open neatlogs / Entire / cfo.ai. Copilot debugs; oncall acts.",
  ]
    .filter(Boolean)
    .join("\n");

  const dir = path.join(retrenchStateDir(), "inbox");
  await fs.mkdir(dir, { recursive: true });
  const payload = {
    at: new Date().toISOString(),
    message,
    workflow: primary.featureId,
    decision: primary.decision,
    cliff: primary.cliff,
    ok: primary.okTraces,
    err: primary.errorTraces,
    rate: primary.liveSuccessRate,
    briefPath: state.briefs.find((b) => b.featureId === primary.featureId)?.path,
    paused: primary.paused,
    watchdog: primary.watchdog?.detail,
  };
  await fs.writeFile(
    path.join(dir, "latest.json"),
    JSON.stringify(payload, null, 2),
    "utf8"
  );
}

