/**
 * Catalog of spawnable agents (user picks one, gives a goal, we run it).
 * Not a neatlogs ticker — each entry is a real worker process.
 */

export type AgentDefinition = {
  id: string;
  name: string;
  tagline: string;
  description: string;
  script: string; // relative to repo root
  goalPlaceholder: string;
  tools: string[];
  /** checkout_agent is left alone — not in spawn catalog */
};

export const AGENT_CATALOG: AgentDefinition[] = [
  {
    id: "scout",
    name: "Scout",
    tagline: "Research a company or person with real Crustdata",
    description:
      "Takes a domain, company name, or LinkedIn URL. Calls Crustdata (live), summarizes with your model, logs the run to neatlogs, writes a spend ledger for cfo.ai, and drops an Entire session note.",
    script: "demo/agents/scout_agent.py",
    goalPlaceholder: "retool.com  or  https://www.linkedin.com/in/…",
    tools: ["crustdata", "neatlogs", "openrouter", "cfo.ai-ledger", "entire"],
  },
];

export function getAgent(id: string) {
  return AGENT_CATALOG.find((a) => a.id === id);
}

import { promises as fs } from "fs";
import path from "path";
import { retrenchStateDir } from "./oncall-store";

export type AgentRun = {
  runId: string;
  agentId: string;
  goal: string;
  status: string;
  updatedAt?: string;
  error?: string;
  reportPath?: string;
  spend?: Record<string, unknown>;
  crustdata?: Record<string, unknown>;
  steps?: string[];
  kind?: string;
  entireNote?: string;
};

function runsRoot() {
  return path.join(retrenchStateDir(), "runs");
}

export async function listRuns(limit = 40): Promise<AgentRun[]> {
  const root = runsRoot();
  let dirs: string[] = [];
  try {
    dirs = await fs.readdir(root);
  } catch {
    return [];
  }
  const out: AgentRun[] = [];
  for (const id of dirs) {
    try {
      const raw = await fs.readFile(path.join(root, id, "run.json"), "utf8");
      out.push(JSON.parse(raw) as AgentRun);
    } catch {
      /* skip */
    }
  }
  out.sort((a, b) => (b.updatedAt || "").localeCompare(a.updatedAt || ""));
  return out.slice(0, limit);
}

export async function readRun(runId: string): Promise<AgentRun | null> {
  try {
    const raw = await fs.readFile(
      path.join(runsRoot(), runId, "run.json"),
      "utf8"
    );
    return JSON.parse(raw) as AgentRun;
  } catch {
    return null;
  }
}

export async function readReport(runId: string): Promise<string | null> {
  try {
    return await fs.readFile(
      path.join(runsRoot(), runId, "report.md"),
      "utf8"
    );
  } catch {
    return null;
  }
}

import { NextResponse } from "next/server";
import { AGENT_CATALOG } from "@/lib/agent-registry";
import { listRuns } from "@/lib/runs-store";

export const dynamic = "force-dynamic";

/** List spawnable agents + recent runs (user catalog). */
export async function GET() {
  const runs = await listRuns();
  return NextResponse.json({
    agents: AGENT_CATALOG,
    runs,
    howToSpawn:
      "POST /api/agents/spawn { agentId, goal } — or on EC2: python3 demo/agents/scout_agent.py --goal 'retool.com'",
  });
}

import { NextResponse } from "next/server";
import { spawn } from "child_process";
import path from "path";
import { promises as fs } from "fs";
import { getAgent } from "@/lib/agent-registry";
import { retrenchStateDir } from "@/lib/oncall-store";

export const dynamic = "force-dynamic";
export const maxDuration = 60;

function repoRoot() {
  return path.resolve(/* turbopackIgnore: true */ process.cwd(), "..");
}

/**
 * Spawn a real worker process (Scout, …). Not a neatlogs ticker.
 * Multiple concurrent spawns = multiple agents working different goals.
 */
export async function POST(req: Request) {
  const body = (await req.json().catch(() => ({}))) as {
    agentId?: string;
    goal?: string;
  };
  const agentId = body.agentId || "scout";
  const goal = (body.goal || "").trim();
  if (!goal) {
    return NextResponse.json({ error: "goal is required" }, { status: 400 });
  }
  const agent = getAgent(agentId);
  if (!agent) {
    return NextResponse.json({ error: `unknown agent: ${agentId}` }, { status: 404 });
  }

  const runId = new Date().toISOString().replace(/[:.]/g, "-");
  const root = repoRoot();
  const script = path.join(root, agent.script);
  const runDir = path.join(retrenchStateDir(), "runs", runId);
  await fs.mkdir(runDir, { recursive: true });
  await fs.writeFile(
    path.join(runDir, "run.json"),
    JSON.stringify(
      {
        runId,
        agentId,
        goal,
        status: "queued",
        updatedAt: new Date().toISOString(),
      },
      null,
      2
    ),
    "utf8"
  );

  const py = process.env.PYTHON_PATH || "python3";
  const child = spawn(
    py,
    [script, "--goal", goal, "--run-id", runId, "--agent-id", agentId],
    {
      cwd: root,
      env: {
        ...process.env,
        RETRENCH_STATE_DIR: retrenchStateDir(),
      },
      detached: true,
      stdio: "ignore",
    }
  );
  child.unref();

  return NextResponse.json({
    ok: true,
    runId,
    agentId,
    goal,
    message:
      "Agent spawned. Poll GET /api/agents/runs/" +
      runId +
      " or refresh the Agents page. Spawn again with another goal to run multiple in parallel.",
  });
}

import { NextResponse } from "next/server";
import { readReport, readRun } from "@/lib/runs-store";

export const dynamic = "force-dynamic";

export async function GET(
  _req: Request,
  ctx: { params: Promise<{ id: string }> }
) {
  const { id } = await ctx.params;
  const run = await readRun(id);
  if (!run) {
    return NextResponse.json({ error: "run not found" }, { status: 404 });
  }
  const report = await readReport(id);
  return NextResponse.json({ run, report });
}

