"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { Bot, Loader2, Plus, Rocket, Sparkles } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";

type AgentDef = {
  id: string;
  name: string;
  tagline: string;
  description: string;
  goalPlaceholder: string;
  tools: string[];
};

type Run = {
  runId: string;
  agentId: string;
  goal: string;
  status: string;
  updatedAt?: string;
  error?: string;
  spend?: { totalUsd?: number; crustdataCredits?: number };
  reportPath?: string;
};

export function AgentsWorkspace() {
  const [agents, setAgents] = useState<AgentDef[]>([]);
  const [runs, setRuns] = useState<Run[]>([]);
  const [agentId, setAgentId] = useState("scout");
  const [goal, setGoal] = useState("retool.com");
  const [error, setError] = useState<string | null>(null);
  const [selectedReport, setSelectedReport] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const res = await fetch("/api/agents", { cache: "no-store" });
      const json = await res.json();
      setAgents(json.agents || []);
      setRuns(json.runs || []);
    });
  }, []);

  useEffect(() => {
    refresh();
    const id = setInterval(refresh, 4000);
    return () => clearInterval(id);
  }, [refresh]);

  const selected = agents.find((a) => a.id === agentId) || agents[0];

  function spawn() {
    setError(null);
    setSelectedReport(null);
    start(async () => {
      try {
        const res = await fetch("/api/agents/spawn", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ agentId: selected?.id || "scout", goal }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || "spawn failed");
        refresh();
      } catch (e) {
        setError(e instanceof Error ? e.message : "spawn failed");
      }
    });
  }

  function openRun(runId: string) {
    start(async () => {
      const res = await fetch(`/api/agents/runs/${runId}`, { cache: "no-store" });
      const json = await res.json();
      setSelectedReport(json.report || json.run?.error || "No report yet.");
    });
  }

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-col gap-8 px-4 py-10 sm:px-6">
      <section className="retrench-enter relative overflow-hidden rounded-2xl border bg-card p-8 shadow-sm sm:p-10">
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,oklch(0.92_0.04_145_/_0.5),transparent_55%)]" />
        <div className="relative max-w-2xl space-y-4">
          <Badge className="rounded-md bg-primary text-primary-foreground hover:bg-primary">
            spawn agents · do real work
          </Badge>
          <h1 className="text-3xl font-semibold tracking-tight sm:text-4xl">
            Tell an agent what to do.
            <span className="mt-1 block text-muted-foreground">
              It researches, spends credits, logs the run, and comes back.
            </span>
          </h1>
          <p className="text-base text-muted-foreground">
            Not a keep/kill ticker. Pick Scout, give a company domain or LinkedIn
            URL, spawn it. Spawn again for another goal — that&apos;s how you run
            multiple agents. Crustdata is live data; neatlogs gets the trace;
            spend lands in a cfo ledger; Entire gets a session note.
          </p>
        </div>
      </section>

      <div className="grid gap-6 lg:grid-cols-[1fr_1.1fr]">
        <Card className="shadow-sm">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Rocket className="size-4" />
              Spawn an agent
            </CardTitle>
            <CardDescription>
              One goal per run. Hit spawn again to run another in parallel.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex flex-wrap gap-2">
              {agents.map((a) => (
                <Button
                  key={a.id}
                  type="button"
                  size="sm"
                  variant={a.id === (selected?.id || agentId) ? "default" : "outline"}
                  className="gap-1.5"
                  onClick={() => setAgentId(a.id)}
                >
                  <Bot className="size-3.5" />
                  {a.name}
                </Button>
              ))}
            </div>
            {selected ? (
              <Alert>
                <Sparkles className="size-4" />
                <AlertTitle>{selected.tagline}</AlertTitle>
                <AlertDescription className="space-y-2">
                  <p>{selected.description}</p>
                  <div className="flex flex-wrap gap-1.5">
                    {selected.tools.map((t) => (
                      <Badge key={t} variant="outline" className="rounded-md font-normal">
                        {t}
                      </Badge>
                    ))}
                  </div>
                </AlertDescription>
              </Alert>
            ) : null}

            <div className="space-y-2">
              <label className="text-sm font-medium" htmlFor="goal">
                Goal
              </label>
              <input
                id="goal"
                value={goal}
                onChange={(e) => setGoal(e.target.value)}
                placeholder={selected?.goalPlaceholder}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm shadow-sm outline-none ring-offset-background focus-visible:ring-2 focus-visible:ring-ring"
              />
            </div>

            {error ? (
              <Alert variant="destructive">
                <AlertTitle>Spawn failed</AlertTitle>
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            ) : null}

            <Button
              type="button"
              className="w-full gap-1.5 sm:w-auto"
              disabled={pending || !goal.trim()}
              onClick={spawn}
            >
              {pending ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <Plus className="size-3.5" />
              )}
              Spawn {selected?.name || "agent"}
            </Button>

            <p className="text-xs text-muted-foreground">
              Needs <code className="font-mono">CRUSTDATA_API_KEY</code>,{" "}
              <code className="font-mono">NEATLOGS_API_KEY</code>,{" "}
              <code className="font-mono">OPENROUTER_API_KEY</code> in{" "}
              <code className="font-mono">web/.env.local</code>. No fake
              enrichment.
            </p>
          </CardContent>
        </Card>

        <Card className="shadow-sm">
          <CardHeader className="flex flex-row items-center justify-between space-y-0">
            <div>
              <CardTitle className="text-base">Your runs</CardTitle>
              <CardDescription>
                Each row is one agent instance you spawned
              </CardDescription>
            </div>
            <Button type="button" variant="outline" size="sm" onClick={refresh}>
              Refresh
            </Button>
          </CardHeader>
          <CardContent className="space-y-3">
            {runs.length === 0 ? (
              <p className="text-sm text-muted-foreground">
                No runs yet. Spawn Scout with a real company domain.
              </p>
            ) : (
              runs.map((r) => (
                <button
                  key={r.runId}
                  type="button"
                  onClick={() => openRun(r.runId)}
                  className="flex w-full flex-col gap-1 rounded-xl border p-3 text-left text-sm transition hover:bg-muted/40"
                >
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <span className="font-medium">{r.goal}</span>
                    <Badge
                      className={
                        r.status === "completed"
                          ? "rounded-md bg-emerald-700 text-white hover:bg-emerald-700"
                          : r.status === "failed"
                            ? "rounded-md bg-red-700 text-white hover:bg-red-700"
                            : "rounded-md"
                      }
                    >
                      {r.status}
                    </Badge>
                  </div>
                  <div className="text-xs text-muted-foreground">
                    {r.agentId} · {r.runId}
                    {r.spend?.crustdataCredits != null
                      ? ` · ${r.spend.crustdataCredits} credits`
                      : ""}
                    {r.spend?.totalUsd != null
                      ? ` · ~$${Number(r.spend.totalUsd).toFixed(3)}`
                      : ""}
                  </div>
                  {r.error ? (
                    <p className="text-xs text-red-700">{r.error}</p>
                  ) : null}
                </button>
              ))
            )}
          </CardContent>
        </Card>
      </div>

      {selectedReport ? (
        <Card className="shadow-sm">
          <CardHeader>
            <CardTitle className="text-base">Report</CardTitle>
            <CardDescription>What the agent brought back</CardDescription>
          </CardHeader>
          <CardContent>
            <pre className="max-h-[480px] overflow-auto whitespace-pre-wrap rounded-xl border bg-muted/20 p-4 font-mono text-xs leading-relaxed">
              {selectedReport}
            </pre>
          </CardContent>
        </Card>
      ) : null}

      <Separator />

      <section className="space-y-3 text-sm text-muted-foreground">
        <h2 className="text-sm font-semibold text-foreground">
          How do I add / spawn multiple agents?
        </h2>
        <ol className="list-decimal space-y-2 pl-5">
          <li>
            <strong className="text-foreground">Same agent, many goals:</strong>{" "}
            spawn Scout with <code className="font-mono text-xs">retool.com</code>,
            then spawn again with another domain — parallel runs under{" "}
            <code className="font-mono text-xs">.retrench/runs/</code>.
          </li>
          <li>
            <strong className="text-foreground">New agent types:</strong> add an
            entry in <code className="font-mono text-xs">web/src/lib/agent-registry.ts</code>{" "}
            + a Python worker under <code className="font-mono text-xs">demo/agents/</code>{" "}
            (checkout_agent stays out of this catalog for now).
          </li>
          <li>
            <strong className="text-foreground">On EC2:</strong>{" "}
            <code className="font-mono text-xs">
              python3 demo/agents/scout_agent.py --goal &apos;stripe.com&apos;
            </code>{" "}
            as many times as you want, or use this UI behind your ALB.
          </li>
        </ol>
        <p>
          Portfolio / old oncall ticker:{" "}
          <Link href="/portfolio" className="font-medium text-foreground underline-offset-4 hover:underline">
            /portfolio
          </Link>
          .
        </p>
      </section>
    </div>
  );
}

