import { promises as fs } from "fs";
import path from "path";
import { randomUUID } from "crypto";
import { retrenchStateDir } from "./oncall-store";

/** An agent the USER owns — Retrench only runs/tests it. */
export type UserAgent = {
  id: string;
  name: string;
  description?: string;
  /** Shell command to execute one test run (their code, not ours). */
  command: string;
  /** Working directory relative to repo root, or absolute on the server. */
  cwd?: string;
  /** neatlogs workflow_name they use (for linking traces). */
  workflowName?: string;
  createdAt: string;
  updatedAt: string;
};

function catalogPath() {
  return path.join(retrenchStateDir(), "user-agents.json");
}

async function readAll(): Promise<UserAgent[]> {
  try {
    const raw = await fs.readFile(catalogPath(), "utf8");
    const parsed = JSON.parse(raw) as { agents?: UserAgent[] };
    return Array.isArray(parsed.agents) ? parsed.agents : [];
  } catch {
    return [];
  }
}

async function writeAll(agents: UserAgent[]) {
  await fs.mkdir(retrenchStateDir(), { recursive: true });
  await fs.writeFile(
    catalogPath(),
    JSON.stringify({ version: 1, agents }, null, 2),
    "utf8"
  );
}

export async function listUserAgents() {
  return readAll();
}

export async function getUserAgent(id: string) {
  return (await readAll()).find((a) => a.id === id) ?? null;
}

export async function createUserAgent(input: {
  name: string;
  command: string;
  description?: string;
  cwd?: string;
  workflowName?: string;
}) {
  const name = input.name.trim();
  const command = input.command.trim();
  if (!name || !command) {
    throw new Error("name and command are required");
  }
  const now = new Date().toISOString();
  const agent: UserAgent = {
    id: randomUUID().slice(0, 8),
    name,
    command,
    description: input.description?.trim() || undefined,
    cwd: input.cwd?.trim() || undefined,
    workflowName: input.workflowName?.trim() || undefined,
    createdAt: now,
    updatedAt: now,
  };
  const agents = await readAll();
  agents.unshift(agent);
  await writeAll(agents);
  return agent;
}

export async function deleteUserAgent(id: string) {
  const agents = await readAll();
  const next = agents.filter((a) => a.id !== id);
  if (next.length === agents.length) return false;
  await writeAll(next);
  return true;
}

import { NextResponse } from "next/server";
import {
  createUserAgent,
  listUserAgents,
} from "@/lib/user-agents";
import { listRuns } from "@/lib/runs-store";

export const dynamic = "force-dynamic";

export async function GET() {
  const [agents, runs] = await Promise.all([
    listUserAgents(),
    listRuns(50),
  ]);
  const tests = runs.filter(
    (r) => (r as { kind?: string }).kind === "user-test" || !r.goal?.includes?.("scout")
  );
  // Prefer runs that look like user tests
  const userRuns = runs.filter(
    (r) =>
      (r as { kind?: string }).kind === "user-test" ||
      Boolean((r as { agentName?: string }).agentName)
  );
  return NextResponse.json({
    agents,
    runs: userRuns.length ? userRuns : tests,
    product:
      "Bring YOUR agent. Retrench runs a test, captures logs, spend stub, Entire note. Instrument with neatlogs for real traces.",
  });
}

export async function POST(req: Request) {
  try {
    const body = (await req.json()) as {
      name?: string;
      command?: string;
      description?: string;
      cwd?: string;
      workflowName?: string;
    };
    const agent = await createUserAgent({
      name: body.name || "",
      command: body.command || "",
      description: body.description,
      cwd: body.cwd,
      workflowName: body.workflowName,
    });
    return NextResponse.json({ agent });
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "failed" },
      { status: 400 }
    );
  }
}

import { NextResponse } from "next/server";
