export const dynamic = "force-dynamic";

export async function GET(
  _req: Request,
  ctx: { params: Promise<{ id: string }> }
) {
  const { id } = await ctx.params;
  const agent = await getUserAgent(id);
  if (!agent) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  return NextResponse.json({ agent });
}

export async function DELETE(
  _req: Request,
  ctx: { params: Promise<{ id: string }> }
) {
  const { id } = await ctx.params;
  const ok = await deleteUserAgent(id);
  if (!ok) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { spawn } from "child_process";
import path from "path";
import { promises as fs } from "fs";
import { getUserAgent } from "@/lib/user-agents";
import { retrenchStateDir } from "@/lib/oncall-store";

export const dynamic = "force-dynamic";

function repoRoot() {
  return path.resolve(/* turbopackIgnore: true */ process.cwd(), "..");
}

/** Start a test run of the USER's agent (their command). */
export async function POST(
  req: Request,
  ctx: { params: Promise<{ id: string }> }
) {
  const { id } = await ctx.params;
  const agent = await getUserAgent(id);
  if (!agent) {
    return NextResponse.json({ error: "agent not found" }, { status: 404 });
  }

  const body = (await req.json().catch(() => ({}))) as { goal?: string };
  const goal = (body.goal || "").trim();
  const runId = new Date().toISOString().replace(/[:.]/g, "-");
  const root = repoRoot();
  const runDir = path.join(retrenchStateDir(), "runs", runId);
  await fs.mkdir(runDir, { recursive: true });
  await fs.writeFile(
    path.join(runDir, "run.json"),
    JSON.stringify(
      {
        runId,
        agentId: id,
        agentName: agent.name,
        kind: "user-test",
        goal: goal || "(no goal)",
        command: agent.command,
        status: "queued",
        updatedAt: new Date().toISOString(),
      },
      null,
      2
    ),
    "utf8"
  );

  const py =
    process.env.PYTHON_PATH ||
    (process.platform === "win32" ? "python" : "python3");
  const script = path.join(root, "demo/agents/run_user_agent.py");
  const args = [
    script,
    "--agent-id",
    id,
    "--run-id",
    runId,
  ];
  if (goal) args.push("--goal", goal);

  const child = spawn(py, args, {
    cwd: root,
    env: {
      ...process.env,
      RETRENCH_STATE_DIR: retrenchStateDir(),
    },
    detached: process.platform !== "win32",
    stdio: "ignore",
    windowsHide: true,
  });
  if (process.platform !== "win32") child.unref();
  child.on("error", async (err) => {
    await fs.writeFile(
      path.join(runDir, "run.json"),
      JSON.stringify(
        {
          runId,
          agentId: id,
          agentName: agent.name,
          kind: "user-test",
          status: "failed",
          error: err.message,
          updatedAt: new Date().toISOString(),
        },
        null,
        2
      ),
      "utf8"
    );
  });

  return NextResponse.json({
    ok: true,
    runId,
    agentId: id,
    message:
      "Testing YOUR agent. Poll /api/agents/runs/" +
      runId +
      " for the report. Add neatlogs to your process for live traces.",
  });
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { FlaskConical, Loader2, Play, Plus, Trash2 } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";

type UserAgent = {
  id: string;
  name: string;
  description?: string;
  command: string;
  cwd?: string;
  workflowName?: string;
};

type Run = {
  runId: string;
  agentId: string;
  agentName?: string;
  goal: string;
  status: string;
  command?: string;
  error?: string;
  updatedAt?: string;
  durationSec?: number;
  exitCode?: number;
};

export function MyAgentsWorkspace() {
  const [agents, setAgents] = useState<UserAgent[]>([]);
  const [runs, setRuns] = useState<Run[]>([]);
  const [name, setName] = useState("");
  const [command, setCommand] = useState("");
  const [cwd, setCwd] = useState("");
  const [workflowName, setWorkflowName] = useState("");
  const [description, setDescription] = useState("");
  const [goal, setGoal] = useState("");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [report, setReport] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const res = await fetch("/api/my-agents", { cache: "no-store" });
      const json = await res.json();
      setAgents(json.agents || []);
      setRuns(json.runs || []);
    });
  }, []);

  useEffect(() => {
    refresh();
    const id = setInterval(refresh, 4000);
    return () => clearInterval(id);
  }, [refresh]);

  function addAgent() {
    setError(null);
    start(async () => {
      try {
        const res = await fetch("/api/my-agents", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            name,
            command,
            cwd: cwd || undefined,
            workflowName: workflowName || undefined,
            description: description || undefined,
          }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || "failed");
        setName("");
        setCommand("");
        setCwd("");
        setWorkflowName("");
        setDescription("");
        setSelectedId(json.agent.id);
        refresh();
      } catch (e) {
        setError(e instanceof Error ? e.message : "failed");
      }
    });
  }

  function removeAgent(id: string) {
    start(async () => {
      await fetch(`/api/my-agents/${id}`, { method: "DELETE" });
      if (selectedId === id) setSelectedId(null);
      refresh();
    });
  }

  function runTest(id: string) {
    setError(null);
    setReport(null);
    start(async () => {
      try {
        const res = await fetch(`/api/my-agents/${id}/test`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ goal }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || "test failed");
        refresh();
      } catch (e) {
        setError(e instanceof Error ? e.message : "test failed");
      }
    });
  }

  function openRun(runId: string) {
    start(async () => {
      const res = await fetch(`/api/agents/runs/${runId}`, { cache: "no-store" });
      const json = await res.json();
      setReport(json.report || json.run?.error || "No report yet.");
    });
  }

  const selected = agents.find((a) => a.id === selectedId) || agents[0];

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-col gap-8 px-4 py-10 sm:px-6">
      <section className="retrench-enter relative overflow-hidden rounded-2xl border bg-card p-8 shadow-sm sm:p-10">
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top_right,oklch(0.92_0.04_145_/_0.5),transparent_55%)]" />
        <div className="relative max-w-2xl space-y-4">
          <Badge className="rounded-md bg-primary text-primary-foreground hover:bg-primary">
            test your agents
          </Badge>
          <h1 className="text-3xl font-semibold tracking-tight sm:text-4xl">
            Bring your agent.
            <span className="mt-1 block text-muted-foreground">
              We run the test. You keep the code.
            </span>
          </h1>
          <p className="text-base text-muted-foreground">
            Retrench is a test harness — not our Scout demo. Register{" "}
            <strong className="text-foreground">your</strong> command, hit Run
            test, get logs + spend stub + Entire note. Put neatlogs in{" "}
            <em>your</em> process for real traces in your project.
          </p>
        </div>
      </section>

      <div className="grid gap-6 lg:grid-cols-2">
        <Card className="shadow-sm">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Plus className="size-4" />
              Add my agent
            </CardTitle>
            <CardDescription>
              Point at code on this machine (EC2 or laptop). Multiple agents =
              add more rows, run tests on each.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <Field
              label="Name"
              value={name}
              onChange={setName}
              placeholder="checkout-bot"
            />
            <Field
              label="Command (your entrypoint)"
              value={command}
              onChange={setCommand}
              placeholder="python path/to/my_agent.py"
              mono
            />
            <Field
              label="Working directory (optional)"
              value={cwd}
              onChange={setCwd}
              placeholder="relative to repo, or absolute on EC2"
              mono
            />
            <Field
              label="neatlogs workflow name (optional)"
              value={workflowName}
              onChange={setWorkflowName}
              placeholder="my-agent-workflow"
              mono
            />
            <Field
              label="Notes (optional)"
              value={description}
              onChange={setDescription}
              placeholder="What this agent does"
            />
            {error ? (
              <Alert variant="destructive">
                <AlertTitle>Error</AlertTitle>
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            ) : null}
            <Button
              type="button"
              disabled={pending || !name.trim() || !command.trim()}
              onClick={addAgent}
              className="gap-1.5"
            >
              {pending ? (
                <Loader2 className="size-3.5 animate-spin" />
              ) : (
                <Plus className="size-3.5" />
              )}
              Save agent
            </Button>
          </CardContent>
        </Card>

        <Card className="shadow-sm">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <FlaskConical className="size-4" />
              Run a test
            </CardTitle>
            <CardDescription>
              Executes <em>their</em> command with your env keys forwarded
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {agents.length === 0 ? (
              <Alert>
                <AlertTitle>No agents yet</AlertTitle>
                <AlertDescription>
                  Add your agent on the left. Example command after you copy
                  code to the server:{" "}
                  <code className="font-mono text-xs">
                    python /opt/my-agents/bot.py
                  </code>
                </AlertDescription>
              </Alert>
            ) : (
              <>
                <div className="flex flex-wrap gap-2">
                  {agents.map((a) => (
                    <Button
                      key={a.id}
                      type="button"
                      size="sm"
                      variant={
                        a.id === (selected?.id || selectedId)
                          ? "default"
                          : "outline"
                      }
                      onClick={() => setSelectedId(a.id)}
                    >
                      {a.name}
                    </Button>
                  ))}
                </div>
                {selected ? (
                  <div className="space-y-2 rounded-xl border p-3 text-sm">
                    <div className="font-medium">{selected.name}</div>
                    <code className="block break-all font-mono text-xs text-muted-foreground">
                      {selected.command}
                    </code>
                    {selected.workflowName ? (
                      <p className="text-xs text-muted-foreground">
                        neatlogs workflow: {selected.workflowName}
                      </p>
                    ) : null}
                    <Field
                      label="Optional goal / prompt (passed as RETRENCH_TEST_GOAL)"
                      value={goal}
                      onChange={setGoal}
                      placeholder="e.g. recover order NL-10482"
                    />
                    <div className="flex flex-wrap gap-2">
                      <Button
                        type="button"
                        className="gap-1.5"
                        disabled={pending}
                        onClick={() => runTest(selected.id)}
                      >
                        <Play className="size-3.5" />
                        Run test
                      </Button>
                      <Button
                        type="button"
                        variant="outline"
                        size="icon"
                        onClick={() => removeAgent(selected.id)}
                        aria-label="Delete agent"
                      >
                        <Trash2 className="size-3.5" />
                      </Button>
                    </div>
                  </div>
                ) : null}
              </>
            )}
          </CardContent>
        </Card>
      </div>

      <Card className="shadow-sm">
        <CardHeader className="flex flex-row items-center justify-between space-y-0">
          <div>
            <CardTitle className="text-base">Test results</CardTitle>
            <CardDescription>
              Each run is one test of a user-owned agent
            </CardDescription>
          </div>
          <Button type="button" variant="outline" size="sm" onClick={refresh}>
            Refresh
          </Button>
        </CardHeader>
        <CardContent className="space-y-3">
          {runs.length === 0 ? (
            <p className="text-sm text-muted-foreground">No tests yet.</p>
          ) : (
            runs.map((r) => (
              <button
                key={r.runId}
                type="button"
                onClick={() => openRun(r.runId)}
                className="flex w-full flex-col gap-1 rounded-xl border p-3 text-left text-sm transition hover:bg-muted/40"
              >
                <div className="flex flex-wrap items-center justify-between gap-2">
                  <span className="font-medium">
                    {r.agentName || r.agentId} — {r.goal}
                  </span>
                  <Badge
                    className={
                      r.status === "completed"
                        ? "rounded-md bg-emerald-700 text-white hover:bg-emerald-700"
                        : r.status === "failed"
                          ? "rounded-md bg-red-700 text-white hover:bg-red-700"
                          : "rounded-md"
                    }
                  >
                    {r.status}
                  </Badge>
                </div>
                <div className="text-xs text-muted-foreground">
                  {r.command ? `${r.command} · ` : ""}
                  {r.durationSec != null ? `${r.durationSec}s · ` : ""}
                  {r.runId}
                </div>
                {r.error ? (
                  <p className="text-xs text-red-700">{r.error}</p>
                ) : null}
              </button>
            ))
          )}
        </CardContent>
      </Card>

      {report ? (
        <Card className="shadow-sm">
          <CardHeader>
            <CardTitle className="text-base">Report</CardTitle>
          </CardHeader>
          <CardContent>
            <pre className="max-h-[480px] overflow-auto whitespace-pre-wrap rounded-xl border bg-muted/20 p-4 font-mono text-xs leading-relaxed">
              {report}
            </pre>
          </CardContent>
        </Card>
      ) : null}

      <Separator />

      <section className="space-y-2 text-sm text-muted-foreground">
        <h2 className="text-sm font-semibold text-foreground">
          How users connect
        </h2>
        <ol className="list-decimal space-y-1 pl-5">
          <li>Deploy Retrench on EC2 (or run locally) with neatlogs keys in env.</li>
          <li>Copy <strong className="text-foreground">their</strong> agent code onto that machine.</li>
          <li>Add agent here with their start command → Run test.</li>
          <li>
            Inside their code: <code className="font-mono text-xs">neatlogs.init</code>{" "}
            + wrap so traces hit <em>their</em> neatlogs project.
          </li>
        </ol>
        <p>
          Multiple agents: add each one, run tests independently. Retrench does
          not replace their agent — it tests it.
        </p>
      </section>
    </div>
  );
}

function Field({
  label,
  value,
  onChange,
  placeholder,
  mono,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  mono?: boolean;
}) {
  return (
    <div className="space-y-1.5">
      <label className="text-sm font-medium">{label}</label>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className={`flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-ring ${
          mono ? "font-mono text-xs" : ""
        }`}
      />
    </div>
  );
}

