        <section>
          <h1 className="font-[family-name:var(--font-display)] text-3xl font-bold tracking-tight text-[var(--ink)] md:text-4xl">
            Who to reach this week
          </h1>
          <p className="mt-3 max-w-md text-sm leading-relaxed text-[var(--ink-soft)] md:text-base">
            Real triggers from your segment. Open a company, review the draft,
            send only if it fits — Signal Scout never sends for you.
          </p>

          <ul className="mt-10 space-y-0 border-t border-[var(--line)]">
            {signals.map((s) => {
              const selected = s.id === current?.id;
              return (
                <li key={s.id} className="wl-row border-b border-[var(--line)]">
                  <button
                    type="button"
                    onClick={() => setActive(s.id)}
                    className={`flex w-full flex-col gap-1 px-1 py-5 text-left transition ${
