import { NextResponse } from "next/server";
import { fetchDrafts, triggerScout } from "@/lib/scout-agent";

export const maxDuration = 300;

export async function POST(req: Request) {
  try {
    const body = (await req.json()) as { domain?: string; name?: string; company?: string };
    const domain = (body.domain || "").trim() || undefined;
    let name = (body.name || body.company || "").trim() || undefined;

    if (!domain && !name) {
      return NextResponse.json(
        { error: "Provide a company domain or name" },
        { status: 400 },
      );
    }

    // If user typed a domain into the company field
    if (!domain && name && /^[\w.-]+\.[a-zA-Z]{2,}$/.test(name)) {
      const result = await triggerScout({ domain: name.toLowerCase() });
      if (result.status === "complete" && result.matched_company?.domain) {
        const drafts = await fetchDrafts(
          result.matched_company.domain || result.matched_company.name || name,
        );
        return NextResponse.json({ ...result, items: drafts.items });
      }
      return NextResponse.json(result);
    }

    const result = await triggerScout({ domain, name });
    const lookup =
      result.matched_company?.domain ||
      result.matched_company?.name ||
      domain ||
      name ||
      "";
    if (result.status === "complete" && lookup) {
      const drafts = await fetchDrafts(lookup);
      return NextResponse.json({ ...result, items: result.items || drafts.items });
    }
    return NextResponse.json(result);
  } catch (e) {
    return NextResponse.json(
      { status: "failed", error: e instanceof Error ? e.message : "scout failed" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { fetchDrafts } from "@/lib/scout-agent";

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const company = searchParams.get("company") || searchParams.get("q") || "";
  if (!company.trim()) {
    return NextResponse.json({ error: "company required" }, { status: 400 });
  }
  try {
    const data = await fetchDrafts(company.trim());
    return NextResponse.json(data);
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "failed" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import nodemailer from "nodemailer";

type MailBody = {
  to: string;
  subject: string;
  text: string;
  from?: string;
  /** Gmail / Outlook address used as SMTP user */
  email?: string;
  /** App password or SMTP password (sent from client session — demo only) */
  appPassword?: string;
  provider?: "gmail" | "outlook" | "smtp";
  smtpHost?: string;
  smtpPort?: number;
};

function transportFor(body: MailBody) {
  const user = body.email || body.from;
  const pass = body.appPassword;
  if (!user || !pass) {
    throw new Error("Connect your email first (address + app password)");
  }

  if (body.provider === "outlook") {
    return nodemailer.createTransport({
      host: "smtp.office365.com",
      port: 587,
      secure: false,
      auth: { user, pass },
    });
  }

  if (body.provider === "smtp" && body.smtpHost) {
    return nodemailer.createTransport({
      host: body.smtpHost,
      port: body.smtpPort || 587,
      secure: false,
      auth: { user, pass },
    });
  }

  // default Gmail
  return nodemailer.createTransport({
    service: "gmail",
    auth: { user, pass },
  });
}

export async function POST(req: Request) {
  try {
    const body = (await req.json()) as MailBody;
    if (!body.to || !body.subject || !body.text) {
      return NextResponse.json(
        { error: "to, subject, and text are required" },
        { status: 400 },
      );
    }

    const transporter = transportFor(body);
    const from = body.from || body.email;
    const info = await transporter.sendMail({
      from,
      to: body.to,
      subject: body.subject,
      text: body.text,
    });

    return NextResponse.json({
      ok: true,
      messageId: info.messageId,
      accepted: info.accepted,
    });
  } catch (e) {
    return NextResponse.json(
      {
        ok: false,
        error: e instanceof Error ? e.message : "send failed",
      },
      { status: 500 },
    );
  }
}

export type MailSession = {
  provider: "gmail" | "outlook" | "smtp";
  email: string;
  appPassword: string;
  smtpHost?: string;
  smtpPort?: number;
  connectedAt: string;
};

const KEY = "signalscout.mail";

export function loadMailSession(): MailSession | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return null;
    return JSON.parse(raw) as MailSession;
  } catch {
    return null;
  }
}

export function saveMailSession(session: MailSession) {
  localStorage.setItem(KEY, JSON.stringify(session));
}

export function clearMailSession() {
  localStorage.removeItem(KEY);
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  clearMailSession,
  loadMailSession,
  saveMailSession,
  type MailSession,
} from "@/lib/mail-session";
import { toast } from "sonner";

export function ConnectMailDialog({
  onChange,
}: {
  onChange?: (session: MailSession | null) => void;
}) {
  const [open, setOpen] = useState(false);
  const [session, setSession] = useState<MailSession | null>(null);
  const [provider, setProvider] = useState<MailSession["provider"]>("gmail");
  const [email, setEmail] = useState("");
  const [appPassword, setAppPassword] = useState("");
  const [smtpHost, setSmtpHost] = useState("");

  useEffect(() => {
    const s = loadMailSession();
    setSession(s);
    if (s) {
      setProvider(s.provider);
      setEmail(s.email);
      setSmtpHost(s.smtpHost || "");
    }
    onChange?.(s);
  }, [onChange]);

  function connect() {
    if (!email.trim() || !appPassword.trim()) {
      toast.error("Email and app password required");
      return;
    }
    const next: MailSession = {
      provider,
      email: email.trim(),
      appPassword: appPassword.trim(),
      smtpHost: provider === "smtp" ? smtpHost.trim() : undefined,
      smtpPort: provider === "smtp" ? 587 : undefined,
      connectedAt: new Date().toISOString(),
    };
    saveMailSession(next);
    setSession(next);
    onChange?.(next);
    setAppPassword("");
    setOpen(false);
    toast.success(`Connected ${next.email}`);
  }

  function disconnect() {
    clearMailSession();
    setSession(null);
    onChange?.(null);
    toast.message("Email disconnected");
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant={session ? "secondary" : "outline"} size="sm">
          {session ? `Mail · ${session.email}` : "Connect email"}
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Connect your mail</DialogTitle>
          <DialogDescription>
            Use a Gmail / Outlook app password so you can send drafts yourself.
            Credentials stay in this browser only.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-2">
          <div className="grid gap-2">
            <Label>Provider</Label>
            <Select
              value={provider}
              onValueChange={(v) => setProvider(v as MailSession["provider"])}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="gmail">Gmail</SelectItem>
                <SelectItem value="outlook">Outlook</SelectItem>
                <SelectItem value="smtp">Custom SMTP</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="mail-email">Email</Label>
            <Input
              id="mail-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@company.com"
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="mail-pass">App password</Label>
            <Input
              id="mail-pass"
              type="password"
              value={appPassword}
              onChange={(e) => setAppPassword(e.target.value)}
              placeholder="16-character app password"
            />
          </div>
          {provider === "smtp" ? (
            <div className="grid gap-2">
              <Label htmlFor="smtp-host">SMTP host</Label>
              <Input
                id="smtp-host"
                value={smtpHost}
                onChange={(e) => setSmtpHost(e.target.value)}
                placeholder="smtp.example.com"
              />
            </div>
          ) : null}
        </div>
        <DialogFooter className="gap-2 sm:gap-0">
          {session ? (
            <Button type="button" variant="ghost" onClick={disconnect}>
              Disconnect
            </Button>
          ) : null}
          <Button type="button" onClick={connect}>
            Save connection
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import Link from "next/link";
