export type ContactRow = {
  name: string;
  title: string;
  profile_url?: string | null;
  emails: string[];
};

export async function findContacts(input: {
  domain: string;
  titles?: string[];
  verified?: boolean;
  limit?: number;
}): Promise<{
  status: string;
  domain?: string;
  contacts: ContactRow[];
  credits_spent?: number;
  error?: string;
  demo?: boolean;
}> {
  if (!AGENT) {
    return demoContacts(input.domain);
  }
  try {
    const res = await fetch(`${AGENT}/contacts`, {
      method: "POST",
      headers: headers(),
      body: JSON.stringify(input),
      cache: "no-store",
      signal: AbortSignal.timeout(120_000),
    });
    const data = await readJson(res);
    if (!res.ok) {
      if (FALLBACK) {
        return {
          ...demoContacts(input.domain),
          error: String(data.error || `agent HTTP ${res.status}`),
        };
      }
      return {
        status: "failed",
        domain: input.domain,
        contacts: [],
        error: String(data.error || `agent HTTP ${res.status}`),
      };
    }
    return data as {
      status: string;
      domain?: string;
      contacts: ContactRow[];
      credits_spent?: number;
      error?: string;
    };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "contacts failed";
    if (FALLBACK) return { ...demoContacts(input.domain), error: msg };
    return {
      status: "failed",
      domain: input.domain,
      contacts: [],
      error: msg,
    };
  }
}

