import NextAuth from "next-auth";
import Google from "next-auth/providers/google";

export const { handlers, signIn, signOut, auth } = NextAuth({
  providers: [
    Google({
      clientId: process.env.AUTH_GOOGLE_ID,
      clientSecret: process.env.AUTH_GOOGLE_SECRET,
      authorization: {
        params: {
          prompt: "consent",
          access_type: "offline",
          response_type: "code",
        },
      },
    }),
  ],
  pages: {
    signIn: "/login",
  },
  callbacks: {
    async jwt({ token, account, profile }) {
      if (account) {
        token.accessToken = account.access_token;
      }
      if (profile && "picture" in profile) {
        token.picture = profile.picture as string | undefined;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        session.user.image = (token.picture as string) || session.user.image;
      }
      return session;
    },
  },
  trustHost: true,
});

"use client";

import { SessionProvider } from "next-auth/react";

export function Providers({ children }: { children: React.ReactNode }) {
  return <SessionProvider>{children}</SessionProvider>;
}

"use client";

import { signIn, signOut, useSession } from "next-auth/react";
import { Button } from "@/components/ui/button";
import { ButtonLink } from "@/components/ui/button-link";

export function AuthButton() {
  const { data, status } = useSession();

  if (status === "loading") {
    return (
      <Button variant="outline" size="sm" disabled>
        …
      </Button>
    );
  }

  if (!data?.user) {
    return (
      <Button size="sm" onClick={() => void signIn("google", { callbackUrl: "/scout" })}>
        Sign in with Google
      </Button>
    );
  }

  const label = data.user.email || data.user.name || "Account";

  return (
    <div className="flex items-center gap-2">
      <div className="hidden max-w-[160px] truncate text-right text-xs text-muted-foreground sm:block">
        {label}
      </div>
      {data.user.image ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={data.user.image}
          alt=""
          className="size-7 rounded-full border border-border"
        />
      ) : null}
      <Button
        variant="outline"
        size="sm"
        onClick={() => void signOut({ callbackUrl: "/" })}
      >
        Sign out
      </Button>
    </div>
  );
}

export function AuthGateHint() {
  const { data, status } = useSession();
  if (status === "loading" || data?.user) return null;
  return (
    <div className="rounded-lg border border-border bg-card px-4 py-3 text-sm text-muted-foreground">
      Sign in with Google to personalize outreach from your account.{" "}
      <ButtonLink href="/login" variant="link" size="sm" className="h-auto px-0">
        Sign in
      </ButtonLink>
    </div>
  );
}

