}

.gtm-canvas {
  background:
    radial-gradient(ellipse 70% 50% at 50% -10%, oklch(0.35 0.12 25 / 0.35), transparent 55%),
    oklch(0.1 0.005 260);
}

.gtm-panel {
  background: oklch(0.14 0.005 260);
  border: 1px solid oklch(1 0 0 / 10%);
}

