const visibleCompanies: TargetCompany[] = useMemo(() => {
  const raw =
    activeIndustry === "all"
      ? categories.flatMap((c) => c.companies)
      : categories.find((c) => c.industry === activeIndustry)?.companies ||
        [];
  // Dedupe by domain (then name) so React keys stay unique across categories
  const byKey = new Map<string, TargetCompany>();
  for (const c of raw) {
    const key = `${(c.domain || "").toLowerCase()}::${(c.name || "").toLowerCase()}`;
    const prev = byKey.get(key);
    if (!prev || (c.draft_count ?? 0) > (prev.draft_count ?? 0)) {
      byKey.set(key, c);
    }
  }
  return Array.from(byKey.values());
}, [categories, activeIndustry]);

