"use client";

import { CheckIcon, FileTextIcon, MailIcon, SearchIcon, SendIcon } from "lucide-react";
import { Frame, FramePanel } from "@/components/reui/frame";
import {
  Stepper,
  StepperContent,
  StepperIndicator,
  StepperItem,
  StepperNav,
  StepperPanel,
  StepperTitle,
  StepperTrigger,
} from "@/components/reui/stepper";
import { cn } from "@/lib/utils";

export const SCOUT_FLOW_STEPS = [
  {
    title: "Searching",
    detail: "Resolve the company and pull live profile signals.",
    icon: <SearchIcon className="size-3.5" aria-hidden="true" />,
  },
  {
    title: "Drafting",
    detail: "Pick a signal and edit the evidence-backed draft.",
    icon: <FileTextIcon className="size-3.5" aria-hidden="true" />,
  },
  {
    title: "Send",
    detail: "Choose a recipient and prepare the message.",
    icon: <MailIcon className="size-3.5" aria-hidden="true" />,
  },
  {
    title: "Sending",
    detail: "Open your mail client — Scout never sends for you.",
    icon: <SendIcon className="size-3.5" aria-hidden="true" />,
  },
] as const;

const completed = <CheckIcon className="size-2.5" aria-hidden="true" />;

type ScoutFlowStepperProps = {
  current: number;
  onStepChange?: (step: number) => void;
  searching?: boolean;
  className?: string;
};

export function ScoutFlowStepper({
  current,
  onStepChange,
  searching = false,
  className,
}: ScoutFlowStepperProps) {
  const steps = SCOUT_FLOW_STEPS;
  const allDone = current > steps.length;

  return (
    <div className={cn("@container w-full", className)}>
      <Stepper
        value={current}
        onValueChange={onStepChange}
        orientation="vertical"
        indicators={{ completed }}
        className="flex flex-col gap-4 @md:flex-row @md:items-start"
        aria-label="Scout workflow"
      >
        <Frame
          variant="ghost"
          spacing="xs"
          className="w-full max-w-48 shrink-0 bg-transparent p-0 [--frame-panel-py-base:--spacing(1.5)]"
        >
          <StepperNav className="gap-1.5">
            {steps.map((item, index) => {
              const step = index + 1;
              return (
                <StepperItem
                  key={item.title}
                  step={step}
                  loading={step === 1 && searching}
                >
                  <StepperTrigger
                    tabIndex={allDone && step === steps.length ? 0 : undefined}
                    render={<FramePanel />}
                    className={cn(
                      "text-muted-foreground hover:bg-muted/50 data-[state=active]:bg-muted/50 data-[state=completed]:text-foreground w-full gap-2 rounded-[calc(var(--frame-panel-radius)-3px)] border-transparent bg-transparent shadow-none data-[state=active]:border-(--frame-panel-border-color) data-[state=active]:text-primary",
                    )}
                  >
                    {item.icon}
                    <StepperTitle className="min-w-0 flex-1 truncate leading-5">
                      {item.title}
                    </StepperTitle>
                    {step < current ? (
                      <span className="sr-only">, completed</span>
                    ) : null}
                    <StepperIndicator className="size-3.5 not-data-[state=completed]:hidden data-[state=completed]:bg-primary data-[state=completed]:text-primary-foreground" />
                    {step === current ? (
                      <span
                        aria-hidden="true"
                        className="pointer-events-none absolute start-0 top-1/2 h-5 w-0.5 -translate-y-1/2 rounded-e-full bg-primary"
                      />
                    ) : null}
                  </StepperTrigger>
                </StepperItem>
              );
            })}
          </StepperNav>
        </Frame>

        <div className="flex min-w-0 flex-1 flex-col gap-2 px-2 text-start @md:px-0">
          <StepperPanel>
            {steps.map((item, index) => (
              <StepperContent key={item.title} value={index + 1}>
                <p className="text-xs text-muted-foreground">
                  Step {index + 1} of {steps.length}
                </p>
                <p className="text-sm font-medium">{item.title}</p>
                <p className="text-sm text-pretty text-muted-foreground">
                  {searching && index === 0
                    ? "Scouting the company now…"
                    : item.detail}
                </p>
              </StepperContent>
            ))}
            <StepperContent value={steps.length + 1}>
              <p className="text-xs text-muted-foreground">
                All {steps.length} steps done
              </p>
              <p className="text-sm font-medium">Ready to follow up</p>
              <p className="text-sm text-pretty text-muted-foreground">
                Mail compose opened. Come back to scout another company anytime.
              </p>
            </StepperContent>
          </StepperPanel>
        </div>
      </Stepper>
    </div>
  );
}

