async function recordHitl(
  action: "approve" | "edit" | "reject",
  opts?: { silent?: boolean },
) {
  setHitlBusy(true);
  try {
    const res = await fetch("/api/draft-action", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        action,
        draft_id: selected?.draft_id,
        signal_id: selected?.signal_id,
        company: selected?.company || companyTitle,
        domain: selected?.domain || company?.domain || query.trim(),
        subject,
        body,
      }),
    });
    const data = await res.json();
    if (!opts?.silent) {
      if (data.logged) {
        toast.success(
          action === "approve"
            ? "Approved — logged to neatlogs"
            : action === "reject"
              ? "Rejected — logged to neatlogs"
              : "Edit logged",
        );
      } else {
        toast.message(
          action === "approve"
            ? "Approved locally"
            : action === "reject"
              ? "Rejected"
              : "Edit saved",
        );
      }
    }
    return data;
  } catch {
    if (!opts?.silent) toast.error("Could not log HITL action");
    return null;
  } finally {
    setHitlBusy(false);
  }
}

