"use client";

import { LoaderIcon } from "lucide-react";
import {
  Progress,
  ProgressLabel,
  ProgressValue,
} from "@/components/ui/progress";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";

export const SCOUT_FLOW_STEPS = [
  {
    title: "Searching",
    detail: "Resolve the company and pull live profile signals.",
  },
  {
    title: "Drafting",
    detail: "Pick a signal and edit the evidence-backed draft.",
  },
  {
    title: "Send",
    detail: "Choose a recipient and prepare the message.",
  },
  {
    title: "Sending",
    detail: "Open your mail client — Scout never sends for you.",
  },
] as const;

type ScoutFlowStepperProps = {
  current: number;
  onStepChange?: (step: number) => void;
  searching?: boolean;
  className?: string;
};

/** Scout workflow progress using shadcn Progress + Tabs. */
export function ScoutFlowStepper({
  current,
  onStepChange,
  searching = false,
  className,
}: ScoutFlowStepperProps) {
  const steps = SCOUT_FLOW_STEPS;
  const active = Math.min(Math.max(current, 1), steps.length);
  const pct = Math.round((active / steps.length) * 100);
  const detail =
    searching && active === 1
      ? "Scouting the company now…"
      : current > steps.length
        ? "Mail compose opened. Scout another company anytime."
        : steps[active - 1]?.detail;

  return (
    <div className={cn("flex w-full flex-col gap-3", className)}>
      <Progress value={pct} className="w-full">
        <ProgressLabel>
          {searching && active === 1 ? (
            <span className="inline-flex items-center gap-1.5">
              <LoaderIcon className="size-3.5 animate-spin" aria-hidden />
              Searching
            </span>
          ) : (
            steps[active - 1]?.title
          )}
        </ProgressLabel>
        <ProgressValue>{() => `${active} of ${steps.length}`}</ProgressValue>
      </Progress>

      <Tabs
        value={String(active)}
        onValueChange={(value) => {
          const next = Number(value);
          if (!Number.isFinite(next)) return;
          onStepChange?.(next);
        }}
        className="w-full gap-2"
      >
        <TabsList className="grid w-full grid-cols-4" variant="default">
          {steps.map((item, index) => {
            const step = index + 1;
            return (
              <TabsTrigger
                key={item.title}
                value={String(step)}
                className="px-1 text-xs sm:text-sm"
              >
                {item.title}
              </TabsTrigger>
            );
          })}
        </TabsList>
      </Tabs>

      {detail ? (
        <p className="text-sm text-muted-foreground">{detail}</p>
      ) : null}
    </div>
  );
}

