                          >
                            {finding ? "Looking up…" : "Find contact"}
                          </Button>
                        </div>
                        <Input
                          id="to"
                          type="email"
                          value={to}
                          onChange={(e) => setTo(e.target.value)}
                          placeholder="name@company.com"
                        />
                      </div>

                      {contacts.length > 0 ? (
                        <div className="rounded-lg border border-border p-3">
                          <ul className="flex flex-col gap-2">
                            {contacts.map((c) => (
                              <li
                                key={`${c.name}-${c.title}-${c.emails[0] || ""}`}
                                className="text-sm"
                              >
                                <p className="font-medium">
                                  {c.name}
                                  {c.title ? (
                                    <span className="font-normal text-muted-foreground">
                                      {" "}
                                      · {c.title}
                                    </span>
                                  ) : null}
                                </p>
                                {c.emails.length ? (
                                  <div className="mt-1 flex flex-wrap gap-1">
                                    {c.emails.map((email) => (
                                      <Button
                                        key={email}
                                        size="xs"
                                        variant="secondary"
                                        onClick={() => {
                                          setTo(email);
                                          toast.success(`Selected ${email}`);
                                        }}
                                      >
                                        {email}
                                      </Button>
                                    ))}
                                  </div>
                                ) : (
                                  <p className="text-xs text-muted-foreground">
                                    No business email
                                  </p>
                                )}
                              </li>
                            ))}
                          </ul>
                        </div>
                      ) : null}

                      <Separator />

                      <div className="flex flex-wrap gap-2">
                        <Button onClick={openInGmail}>Open in Gmail</Button>
                        <Button variant="secondary" onClick={openInOutlook}>
                          Outlook
                        </Button>
                        <Button variant="outline" onClick={openMailApp}>
                          Mail app
                        </Button>
                      </div>
                      <p className="text-xs text-muted-foreground">
                        Signed in as {session?.user?.email || "…"}. Scout never
                        sends for you.
                      </p>
                    </div>
                  </ScrollArea>
                </TabsContent>
              </Tabs>
            ) : (
              <div className="flex h-full items-center justify-center px-(--card-spacing)">
                <p className="max-w-xs text-center text-sm text-muted-foreground">
                  Run a scout to load a draft. Company profile stays on the
                  left.
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

