/** Client-side sent-draft + follow-up store (LangChain GTM–style HITL after compose). */

export type FollowUpStatus = "pending" | "sent" | "skipped";

export type FollowUp = {
  id: string;
  dayOffset: number;
  dueAt: string;
  subject: string;
  body: string;
  status: FollowUpStatus;
};

export type SentChannel = "gmail" | "outlook" | "mailto" | "manual";

export type SentDraft = {
  id: string;
  company: string;
  domain: string;
  to: string;
  subject: string;
  body: string;
  signalSummary?: string;
  draftId?: string | null;
  signalId?: string | null;
  channel: SentChannel;
  sentAt: string;
  followUps: FollowUp[];
};

const STORAGE_KEY = "signal-scout:sent-drafts:v1";

function uid(prefix: string) {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function addDays(iso: string, days: number) {
  const d = new Date(iso);
  d.setDate(d.getDate() + days);
  return d.toISOString();
}

/** Queue +3d / +7d follow-ups after a send — same idea as LangChain GTM enroll-after-approve. */
export function buildFollowUps(input: {
  company: string;
  subject: string;
  signalSummary?: string;
  sentAt: string;
}): FollowUp[] {
  const trigger =
    (input.signalSummary || "").trim() ||
    "your recent company update";
  const firstNameHint = input.company.split(/\s+/)[0] || "there";

  return [
    {
      id: uid("fu"),
      dayOffset: 3,
      dueAt: addDays(input.sentAt, 3),
      subject: `Re: ${input.subject.replace(/^Re:\s*/i, "")}`,
      body: `Hi,\n\nCircling back briefly on ${firstNameHint} — happy to share a short note tied to ${trigger} if useful this week.\n\nBest`,
      status: "pending",
    },
    {
      id: uid("fu"),
      dayOffset: 7,
      dueAt: addDays(input.sentAt, 7),
      subject: `Quick follow-up — ${input.company}`,
      body: `Hi,\n\nOne last nudge on the note about ${trigger}. If timing is off, no worries — glad to reconnect later.\n\nBest`,
      status: "pending",
    },
  ];
}

export function loadSentDrafts(): SentDraft[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as SentDraft[];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveSentDrafts(rows: SentDraft[]) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(rows));
  window.dispatchEvent(new Event("signal-scout:sent-drafts"));
}

export function upsertSentDraft(
  draft: Omit<SentDraft, "id" | "sentAt" | "followUps"> & {
    id?: string;
    sentAt?: string;
    followUps?: FollowUp[];
  },
): SentDraft {
  const sentAt = draft.sentAt || new Date().toISOString();
  const row: SentDraft = {
    id: draft.id || uid("sent"),
    company: draft.company,
    domain: draft.domain,
    to: draft.to,
    subject: draft.subject,
    body: draft.body,
    signalSummary: draft.signalSummary,
    draftId: draft.draftId,
    signalId: draft.signalId,
    channel: draft.channel,
    sentAt,
    followUps:
      draft.followUps ||
      buildFollowUps({
        company: draft.company,
        subject: draft.subject,
        signalSummary: draft.signalSummary,
        sentAt,
      }),
  };
  const existing = loadSentDrafts();
  const next = [row, ...existing.filter((d) => d.id !== row.id)];
  saveSentDrafts(next);
  return row;
}

export function updateFollowUpStatus(
  sentId: string,
  followUpId: string,
  status: FollowUpStatus,
): SentDraft[] {
  const next = loadSentDrafts().map((d) => {
    if (d.id !== sentId) return d;
    return {
      ...d,
      followUps: d.followUps.map((f) =>
        f.id === followUpId ? { ...f, status } : f,
      ),
    };
  });
  saveSentDrafts(next);
  return next;
}

export function deleteSentDraft(id: string): SentDraft[] {
  const next = loadSentDrafts().filter((d) => d.id !== id);
  saveSentDrafts(next);
  return next;
}

export function pendingFollowUps(rows: SentDraft[]) {
  const now = Date.now();
  return rows.flatMap((d) =>
    d.followUps
      .filter((f) => f.status === "pending")
      .map((f) => ({
        ...f,
        sentId: d.id,
        company: d.company,
        domain: d.domain,
        to: d.to,
        overdue: new Date(f.dueAt).getTime() <= now,
      })),
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import {
  deleteSentDraft,
  loadSentDrafts,
  pendingFollowUps,
  type FollowUpStatus,
  type SentChannel,
  type SentDraft,
  updateFollowUpStatus,
  upsertSentDraft,
} from "@/lib/sent-drafts";

export function useSentDrafts() {
  const [drafts, setDrafts] = useState<SentDraft[]>([]);
  const [ready, setReady] = useState(false);

  const refresh = useCallback(() => {
    setDrafts(loadSentDrafts());
    setReady(true);
  }, []);

  useEffect(() => {
    refresh();
    const onStorage = (e: StorageEvent) => {
      if (e.key === null || e.key.startsWith("signal-scout:sent-drafts")) {
        refresh();
      }
    };
    const onCustom = () => refresh();
    window.addEventListener("storage", onStorage);
    window.addEventListener("signal-scout:sent-drafts", onCustom);
    return () => {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener("signal-scout:sent-drafts", onCustom);
    };
  }, [refresh]);

  const markSent = useCallback(
    (input: {
      company: string;
      domain: string;
      to: string;
      subject: string;
      body: string;
      signalSummary?: string;
      draftId?: string | null;
      signalId?: string | null;
      channel: SentChannel;
    }) => {
      const row = upsertSentDraft(input);
      refresh();
      return row;
    },
    [refresh],
  );

  const setFollowUp = useCallback(
    (sentId: string, followUpId: string, status: FollowUpStatus) => {
      setDrafts(updateFollowUpStatus(sentId, followUpId, status));
    },
    [],
  );

  const remove = useCallback((id: string) => {
    setDrafts(deleteSentDraft(id));
  }, []);

  const followUps = pendingFollowUps(drafts);

  return {
    ready,
    drafts,
    followUps,
    markSent,
    setFollowUp,
    remove,
    refresh,
  };
}

"use client";

import { useMemo, useState } from "react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { CompanyAvatar } from "@/components/CompanyAvatar";
import { useSentDrafts } from "@/hooks/use-sent-drafts";
import {
  gmailComposeUrl,
  mailtoUrl,
  outlookComposeUrl,
} from "@/lib/mail-compose";
import { cn } from "@/lib/utils";

function formatWhen(iso?: string | null) {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

type SentDraftsStudioProps = {
  initialTab?: "sent" | "follow-ups";
};

export function SentDraftsStudio({
  initialTab = "sent",
}: SentDraftsStudioProps) {
  const { ready, drafts, followUps, setFollowUp, remove, markSent } =
    useSentDrafts();
  const [tab, setTab] = useState(initialTab);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const selected = useMemo(
    () => drafts.find((d) => d.id === selectedId) || drafts[0] || null,
    [drafts, selectedId],
  );

  function openFollowUp(
    channel: "gmail" | "outlook" | "mailto",
    sentId: string,
    followUpId: string,
    to: string,
    subject: string,
    body: string,
  ) {
    if (channel === "gmail") {
      window.open(
        gmailComposeUrl({ to, subject, body }),
        "_blank",
        "noopener,noreferrer",
      );
    } else if (channel === "outlook") {
      window.open(
        outlookComposeUrl({ to, subject, body }),
        "_blank",
        "noopener,noreferrer",
      );
    } else {
      window.location.href = mailtoUrl({ to, subject, body });
    }
    setFollowUp(sentId, followUpId, "sent");
    toast.success("Follow-up opened — marked sent");
  }

  if (!ready) {
    return (
      <div className="p-6 text-sm text-muted-foreground">Loading sent drafts…</div>
    );
  }

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-col gap-4 px-4 py-4 sm:px-6">
      <div>
        <h1 className="text-lg font-semibold tracking-tight">Sent & follow-ups</h1>
        <p className="text-sm text-muted-foreground">
          Store each compose as sent, then work the +3d / +7d follow-up queue —
          same human-in-the-loop pattern as{" "}
          <a
            href="https://www.langchain.com/blog/how-we-built-langchains-gtm-agent"
            target="_blank"
            rel="noreferrer"
            className="text-primary underline-offset-4 hover:underline"
          >
            LangChain&apos;s GTM agent
          </a>
          .
        </p>
      </div>

      <Tabs
        value={tab}
        onValueChange={(v) => {
          if (v === "sent" || v === "follow-ups") setTab(v);
        }}
        className="gap-4"
      >
        <TabsList>
          <TabsTrigger value="sent">
            Sent ({drafts.length})
          </TabsTrigger>
          <TabsTrigger value="follow-ups">
            Follow-ups ({followUps.length})
          </TabsTrigger>
        </TabsList>

        <TabsContent value="sent" className="mt-0">
          {drafts.length === 0 ? (
            <Card size="sm" className="shadow-none">
              <CardContent className="py-10 text-center text-sm text-muted-foreground">
                No sent drafts yet. From Scout, open Gmail/Outlook and choose
                &quot;Save as sent&quot; — Scout never auto-sends.
              </CardContent>
            </Card>
          ) : (
            <div className="grid gap-3 lg:grid-cols-[0.95fr_1.05fr] lg:items-start">
              <Card size="sm" className="shadow-none">
                <CardHeader className="border-b py-2.5">
                  <CardTitle>Stored sends</CardTitle>
                  <CardDescription>
                    Local to this browser · contact history for do-not-spam
                  </CardDescription>
                </CardHeader>
                <CardContent className="max-h-[min(70vh,36rem)] overflow-y-auto px-0 py-2">
                  <ul className="flex flex-col gap-1.5 px-(--card-spacing)">
                    {drafts.map((d) => {
                      const pending = d.followUps.filter(
                        (f) => f.status === "pending",
                      ).length;
                      const active = selected?.id === d.id;
                      return (
                        <li key={d.id}>
                          <button
                            type="button"
                            onClick={() => setSelectedId(d.id)}
                            className={cn(
                              "flex w-full items-start gap-2 rounded-lg border px-3 py-2.5 text-left transition",
                              active
                                ? "border-primary bg-accent/25"
                                : "border-border hover:bg-secondary/40",
                            )}
                          >
                            <CompanyAvatar
                              name={d.company}
                              domain={d.domain}
                              size="sm"
                            />
                            <span className="min-w-0 flex-1">
                              <span className="block truncate text-sm font-medium">
                                {d.company}
                              </span>
                              <span className="block truncate text-xs text-muted-foreground">
                                {d.to} · {formatWhen(d.sentAt)}
                              </span>
                            </span>
                            {pending > 0 ? (
                              <Badge variant="secondary">{pending} fu</Badge>
                            ) : (
                              <Badge variant="outline">Done</Badge>
                            )}
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                </CardContent>
              </Card>

              {selected ? (
                <Card size="sm" className="shadow-none">
                  <CardHeader className="border-b py-2.5">
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0">
                        <CardTitle className="truncate">
                          {selected.subject}
                        </CardTitle>
                        <CardDescription className="truncate">
                          {selected.to} · via {selected.channel} ·{" "}
                          {formatWhen(selected.sentAt)}
                        </CardDescription>
                      </div>
                      <Button
                        size="xs"
                        variant="outline"
                        onClick={() => {
                          remove(selected.id);
                          setSelectedId(null);
                          toast.message("Removed from sent store");
                        }}
                      >
                        Delete
                      </Button>
                    </div>
                  </CardHeader>
                  <CardContent className="flex max-h-[min(70vh,36rem)] flex-col gap-4 overflow-y-auto py-3">
                    {selected.signalSummary ? (
                      <div className="rounded-lg border border-border bg-secondary/20 px-3 py-2">
                        <p className="text-xs text-muted-foreground">
                          Why it was sent
                        </p>
                        <p className="mt-1 text-sm">{selected.signalSummary}</p>
                      </div>
                    ) : null}
                    <div>
                      <p className="text-xs text-muted-foreground">Body</p>
                      <pre className="mt-1 whitespace-pre-wrap font-sans text-sm leading-relaxed">
                        {selected.body}
                      </pre>
                    </div>
                    <Separator />
                    <div className="flex flex-col gap-2">
                      <p className="text-sm font-medium">Follow-ups</p>
                      {selected.followUps.map((f) => (
                        <div
                          key={f.id}
                          className="rounded-lg border border-border px-3 py-2.5"
                        >
                          <div className="flex flex-wrap items-center justify-between gap-2">
                            <p className="text-sm font-medium">
                              Day +{f.dayOffset} · {formatWhen(f.dueAt)}
                            </p>
                            <Badge
                              variant={
                                f.status === "pending"
                                  ? "default"
                                  : f.status === "sent"
                                    ? "secondary"
                                    : "outline"
                              }
                            >
                              {f.status}
                            </Badge>
                          </div>
                          <p className="mt-1 truncate text-xs text-muted-foreground">
                            {f.subject}
                          </p>
                          {f.status === "pending" ? (
                            <div className="mt-2 flex flex-wrap gap-1.5">
                              <Button
                                size="xs"
                                onClick={() =>
                                  openFollowUp(
                                    "gmail",
                                    selected.id,
                                    f.id,
                                    selected.to,
                                    f.subject,
                                    f.body,
                                  )
                                }
                              >
                                Open Gmail
                              </Button>
                              <Button
                                size="xs"
                                variant="secondary"
                                onClick={() =>
                                  openFollowUp(
                                    "outlook",
                                    selected.id,
                                    f.id,
                                    selected.to,
                                    f.subject,
                                    f.body,
                                  )
                                }
                              >
                                Outlook
                              </Button>
                              <Button
                                size="xs"
                                variant="outline"
                                onClick={() => {
                                  setFollowUp(selected.id, f.id, "skipped");
                                  toast.message("Follow-up skipped");
                                }}
                              >
                                Skip
                              </Button>
                            </div>
                          ) : null}
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              ) : null}
            </div>
          )}
        </TabsContent>

        <TabsContent value="follow-ups" className="mt-0">
          {followUps.length === 0 ? (
            <Card size="sm" className="shadow-none">
              <CardContent className="py-10 text-center text-sm text-muted-foreground">
                No pending follow-ups. Save a sent draft from Scout to enqueue
                day +3 and day +7 nudges.
              </CardContent>
            </Card>
          ) : (
            <ul className="flex flex-col gap-2">
              {followUps.map((f) => (
                <li key={`${f.sentId}-${f.id}`}>
                  <Card size="sm" className="shadow-none">
                    <CardContent className="flex flex-col gap-3 py-3 sm:flex-row sm:items-start sm:justify-between">
                      <div className="min-w-0">
                        <div className="flex flex-wrap items-center gap-2">
                          <p className="font-medium">{f.company}</p>
                          <Badge variant={f.overdue ? "destructive" : "secondary"}>
                            {f.overdue ? "Due" : `Day +${f.dayOffset}`}
                          </Badge>
                          <span className="text-xs text-muted-foreground">
                            {formatWhen(f.dueAt)}
                          </span>
                        </div>
                        <p className="mt-1 truncate text-sm">{f.subject}</p>
                        <p className="mt-1 line-clamp-2 text-xs text-muted-foreground">
                          To {f.to}
                        </p>
                      </div>
                      <div className="flex shrink-0 flex-wrap gap-1.5">
                        <Button
                          size="sm"
                          onClick={() =>
                            openFollowUp(
                              "gmail",
                              f.sentId,
                              f.id,
                              f.to,
                              f.subject,
                              f.body,
                            )
                          }
                        >
                          Send follow-up
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => {
                            setFollowUp(f.sentId, f.id, "skipped");
                            toast.message("Skipped");
                          }}
                        >
                          Skip
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => {
                            setTab("sent");
                            setSelectedId(f.sentId);
                          }}
                        >
                          View thread
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                </li>
              ))}
            </ul>
          )}
        </TabsContent>
      </Tabs>

      {/* keep markSent referenced for future quick-add; silence unused if tree-shaken */}
      <span className="hidden">{String(Boolean(markSent))}</span>
    </div>
  );
}

