export type SendMode = "hitl" | "agent";

export type OutreachPrefs = {
  /** hitl = human sends in Gmail; agent = Scout may send via Gmail API after approve */
  sendMode: SendMode;
  /** Poll Gmail Sent after compose to confirm delivery */
  verifySent: boolean;
  askedAt?: string;
};

const KEY = "signal-scout:outreach-prefs:v1";

export const DEFAULT_OUTREACH_PREFS: OutreachPrefs = {
  sendMode: "hitl",
  verifySent: true,
};

export function loadOutreachPrefs(): OutreachPrefs {
  if (typeof window === "undefined") return DEFAULT_OUTREACH_PREFS;
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return DEFAULT_OUTREACH_PREFS;
    return { ...DEFAULT_OUTREACH_PREFS, ...(JSON.parse(raw) as OutreachPrefs) };
  } catch {
    return DEFAULT_OUTREACH_PREFS;
  }
}

export function saveOutreachPrefs(prefs: OutreachPrefs) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(
    KEY,
    JSON.stringify({ ...prefs, askedAt: prefs.askedAt || new Date().toISOString() }),
  );
  window.dispatchEvent(new Event("signal-scout:outreach-prefs"));
}

export function hasChosenOutreachPrefs(): boolean {
  const p = loadOutreachPrefs();
  return Boolean(p.askedAt);
}

/** Style memory from HITL approve/edit/spam — LangChain GTM–style learning loop. */

export type StyleObservation = {
  id: string;
  at: string;
  kind: "approve" | "edit" | "spam_reject";
  company?: string;
  note: string;
  exampleSubject?: string;
  exampleSnippet?: string;
};

const KEY = "signal-scout:draft-memory:v1";
const MAX = 40;

function uid() {
  return `mem-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
}

export function loadStyleMemory(): StyleObservation[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as StyleObservation[];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function saveStyleMemory(rows: StyleObservation[]) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(KEY, JSON.stringify(rows.slice(0, MAX)));
}

export function rememberApproval(input: {
  company?: string;
  subject: string;
  body: string;
}) {
  const rows = loadStyleMemory();
  rows.unshift({
    id: uid(),
    at: new Date().toISOString(),
    kind: "approve",
    company: input.company,
    note: "Rep approved this draft — prefer similar tone, length, and specificity.",
    exampleSubject: input.subject,
    exampleSnippet: input.body.slice(0, 280),
  });
  saveStyleMemory(rows);
}

export function rememberEdit(input: {
  company?: string;
  beforeSubject: string;
  beforeBody: string;
  afterSubject: string;
  afterBody: string;
}) {
  const changedSubject = input.beforeSubject !== input.afterSubject;
  const beforeLen = input.beforeBody.trim().split(/\s+/).length;
  const afterLen = input.afterBody.trim().split(/\s+/).length;
  const noteParts = [
    changedSubject ? "Subject was edited." : null,
    afterLen < beforeLen
      ? "Rep shortened the body — prefer brevity."
      : afterLen > beforeLen
        ? "Rep expanded the body slightly."
        : "Body wording was refined.",
    "Match the revised voice on future drafts.",
  ].filter(Boolean);
  const rows = loadStyleMemory();
  rows.unshift({
    id: uid(),
    at: new Date().toISOString(),
    kind: "edit",
    company: input.company,
    note: noteParts.join(" "),
    exampleSubject: input.afterSubject,
    exampleSnippet: input.afterBody.slice(0, 280),
  });
  saveStyleMemory(rows);
}

export function rememberSpamReject(input: {
  company?: string;
  subject: string;
  body: string;
}) {
  const rows = loadStyleMemory();
  rows.unshift({
    id: uid(),
    at: new Date().toISOString(),
    kind: "spam_reject",
    company: input.company,
    note:
      "Rep flagged this as spammy. Avoid hype, urgency, vague pitches, ALL CAPS, links, and generic openers. Rewrite for Inbox.",
    exampleSubject: input.subject,
    exampleSnippet: input.body.slice(0, 200),
  });
  saveStyleMemory(rows);
}

export function styleNotesForPrompt(limit = 8): string[] {
  return loadStyleMemory()
    .slice(0, limit)
    .map((m) => {
      const ex = m.exampleSubject ? ` Example subject: "${m.exampleSubject}".` : "";
      return `${m.kind}: ${m.note}${ex}`;
    });
}

import { NextRequest, NextResponse } from "next/server";
import { gmailFindInSent, resolveGmailAccessToken } from "@/lib/gmail";

export async function POST(req: NextRequest) {
  try {
    const accessToken = await resolveGmailAccessToken(req);
    if (!accessToken) {
      return NextResponse.json(
        {
          status: "unauthorized",
          error:
            "Gmail not connected. Sign out and sign in with Google to grant Sent access.",
        },
        { status: 401 },
      );
    }

    const body = (await req.json()) as {
      to?: string;
      subject?: string;
      afterUnixSeconds?: number;
    };
    const to = String(body.to || "").trim();
    const subject = String(body.subject || "").trim();
    if (!to || !subject) {
      return NextResponse.json(
        { status: "failed", error: "to and subject required" },
        { status: 400 },
      );
    }

    const match = await gmailFindInSent({
      accessToken,
      to,
      subject,
      afterUnixSeconds: body.afterUnixSeconds,
    });

    return NextResponse.json({
      status: "ok",
      verified: Boolean(match),
      match,
    });
  } catch (e) {
    return NextResponse.json(
      {
        status: "failed",
        error: e instanceof Error ? e.message : "verify-sent failed",
      },
      { status: 500 },
    );
  }
}

