  async function agentSendFollowUp(
    sentId: string,
    followUpId: string,
    to: string,
    subject: string,
    body: string,
  ) {
    setAgentBusy(true);
    try {
      const res = await fetch("/api/gmail/send", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ to, subject, body }),
