  }, [ready, agentMode, followUps, session?.gmailConnected]);

  function openFollowUp(
    channel: "gmail" | "outlook" | "mailto",
    sentId: string,
    followUpId: string,
    to: string,
    subject: string,
    body: string,
  ) {
